@import url('https://fonts.googleapis.com/css2?family=Gowun+Batang:wght@400;700&family=Gowun+Dodum&family=Inter:wght@400;500;600;700;800&display=swap');

:root {
  color-scheme: only light;
  --ink: #1d2b22;
  --ink-soft: rgba(29, 43, 34, 0.7);
  --card: rgba(255, 250, 240, 0.86);
  --green: #28543f;
  --green-strong: #1d4734;
  --shadow: 0 18px 40px rgba(35, 45, 33, 0.12);
  --font-ko-display: 'Gowun Dodum', 'Inter', 'Malgun Gothic', sans-serif;
  --scrollbar-size: 12px;
  --scrollbar-radius: 999px;
  --scrollbar-track: rgba(57, 95, 73, 0.14);
  --scrollbar-track-hover: rgba(57, 95, 73, 0.2);
  --scrollbar-thumb: linear-gradient(180deg, rgba(251, 247, 236, 0.98), rgba(221, 230, 205, 0.98));
  --scrollbar-thumb-hover: linear-gradient(180deg, rgba(255, 251, 242, 0.99), rgba(232, 239, 218, 0.99));
  --scrollbar-thumb-border: rgba(78, 115, 91, 0.5);
}


* {
  box-sizing: border-box;
  scrollbar-width: thin;
  scrollbar-color: color-mix(in srgb, var(--scrollbar-thumb-border) 58%, white 42%) var(--scrollbar-track);
}

*::-webkit-scrollbar {
  width: var(--scrollbar-size);
  height: var(--scrollbar-size);
}

*::-webkit-scrollbar-track {
  border-radius: var(--scrollbar-radius);
  background: var(--scrollbar-track);
}

*::-webkit-scrollbar-track:hover {
  background: var(--scrollbar-track-hover);
}

*::-webkit-scrollbar-thumb {
  border-radius: var(--scrollbar-radius);
  border: 2px solid var(--scrollbar-thumb-border);
  background: var(--scrollbar-thumb);
}

*::-webkit-scrollbar-thumb:hover {
  background: var(--scrollbar-thumb-hover);
}

*::-webkit-scrollbar-corner {
  background: transparent;
}

html,
body,
#root {
  color-scheme: only light;
  margin: 0;
  min-height: 100%;
  background-color: #f5eedf;
}

html {
  color-scheme: only light;
}

button,
input,
textarea,
select {
  color-scheme: only light;
}

body {
  font-family: var(--font-ko-display);
  color: var(--ink);
  background:
    radial-gradient(circle at top left, rgba(223, 201, 136, 0.46), transparent 28%),
    radial-gradient(circle at bottom right, rgba(103, 143, 90, 0.25), transparent 32%),
    linear-gradient(180deg, #f5eedf 0%, #ebdfc5 100%);
}

.panel-card,
.panel,
.confirm-modal {
  --scrollbar-track: rgba(68, 102, 82, 0.14);
  --scrollbar-track-hover: rgba(68, 102, 82, 0.2);
  --scrollbar-thumb: linear-gradient(180deg, rgba(252, 248, 239, 0.98), rgba(223, 232, 208, 0.98));
  --scrollbar-thumb-hover: linear-gradient(180deg, rgba(255, 251, 243, 0.99), rgba(234, 241, 220, 0.99));
  --scrollbar-thumb-border: rgba(83, 119, 95, 0.48);
}

.hero-card,
.hero-chat-card,
.hero-presence-card,
.hero-gpu-guide {
  --scrollbar-track: rgba(245, 250, 244, 0.12);
  --scrollbar-track-hover: rgba(245, 250, 244, 0.18);
  --scrollbar-thumb: linear-gradient(180deg, rgba(239, 244, 233, 0.92), rgba(182, 198, 172, 0.94));
  --scrollbar-thumb-hover: linear-gradient(180deg, rgba(248, 251, 243, 0.97), rgba(201, 215, 190, 0.97));
  --scrollbar-thumb-border: rgba(18, 45, 33, 0.72);
}

.phone-ui__screen,
.phone-galaxy-home,
.phone-galaxy-weather-app,
.phone-galaxy-calendar-app,
.phone-galaxy-messages-app,
.phone-galaxy-helper-chat,
.phone-galaxy-contacts,
.phone-galaxy-bank-app,
.phone-galaxy-health-app,
.phone-galaxy-placeholder-app,
.phone-galaxy-land-app,
.phone-galaxy-labor-app {
  --scrollbar-track: rgba(196, 214, 255, 0.18);
  --scrollbar-track-hover: rgba(210, 225, 255, 0.24);
  --scrollbar-thumb: linear-gradient(180deg, rgba(243, 248, 255, 0.96), rgba(163, 191, 255, 0.94));
  --scrollbar-thumb-hover: linear-gradient(180deg, rgba(252, 254, 255, 0.99), rgba(186, 208, 255, 0.97));
  --scrollbar-thumb-border: rgba(27, 58, 142, 0.56);
}

button,
input {
  font: inherit;
}

button {
  border: 0;
}

.screen {
  min-height: 100vh;
  position: relative;
  overflow: hidden;
  padding: 32px 20px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.screen--hero {
  background:
    linear-gradient(180deg, rgba(15, 36, 28, 0.42), rgba(15, 36, 28, 0.2)),
    url('./assets/images/main-menu.png');
  background-size: cover;
  background-position: center;
  background-repeat: no-repeat;
}

.hero-gpu-guide {
  position: absolute;
  bottom: 18px;
  right: 18px;
  z-index: 2;
  max-width: min(560px, calc(100vw - 36px));
  padding: 12px 14px;
  border-radius: 14px;
  color: #f5faf4;
  background: rgba(20, 44, 32, 0.78);
  border: 1px solid rgba(255, 255, 255, 0.22);
  box-shadow: 0 10px 24px rgba(12, 26, 19, 0.28);
  backdrop-filter: blur(6px);
  font-size: 13px;
  line-height: 1.45;
}

.hero-chat-card {
  position: absolute;
  top: 18px;
  right: 18px;
  z-index: 2;
  width: min(360px, calc(100vw - 36px));
  height: 388px;
  max-height: 388px;
  padding: 6px 16px;
  border-radius: 18px;
  color: #f5faf4;
  background: rgba(20, 44, 32, 0.82);
  border: 1px solid rgba(255, 255, 255, 0.2);
  box-shadow: 0 10px 24px rgba(12, 26, 19, 0.24);
  backdrop-filter: blur(6px);
  display: flex;
  flex-direction: column;
  overflow: hidden;
  transition: box-shadow 220ms ease, background-color 220ms ease;
}

.hero-chat-card.is-collapsed {
  height: auto;
  max-height: 58px;
  min-height: 58px;
}

.hero-chat-card__header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 6px;
}

.hero-chat-card__header-actions {
  display: flex;
  align-items: center;
  gap: 6px;
}

.hero-chat-card__eyebrow {
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  opacity: 0.76;
}

.hero-chat-card__header strong {
  display: block;
  margin-top: 1px;
  font-size: 0.82rem;
}

.hero-chat-card__toggle {
  min-width: 24px;
  min-height: 24px;
  padding: 0;
  border: 1px solid rgba(255, 255, 255, 0.14);
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.08);
  color: rgba(245, 250, 244, 0.86);
  font-size: 0.8rem;
  line-height: 1;
  cursor: pointer;
  transition: transform 220ms ease, background-color 160ms ease, border-color 160ms ease;
}

.hero-chat-card__toggle:hover {
  background: rgba(255, 255, 255, 0.12);
}

.hero-chat-card.is-collapsed .hero-chat-card__toggle {
  transform: rotate(180deg);
}

.hero-chat-card__badge {
  flex: 0 0 auto;
  padding: 2px 8px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.08);
  border: 1px solid rgba(255, 255, 255, 0.14);
  color: rgba(245, 250, 244, 0.84);
  font-size: 0.68rem;
}

.hero-chat-card__body {
  display: flex;
  flex: 1 1 auto;
  min-height: 0;
  flex-direction: column;
  height: 100%;
  max-height: none;
  opacity: 1;
  transform: translateY(0);
  overflow: hidden;
  transition:
    max-height 280ms cubic-bezier(0.22, 1, 0.36, 1),
    opacity 180ms ease,
    transform 220ms ease,
    margin-top 220ms ease;
}

.hero-chat-card.is-collapsed .hero-chat-card__body {
  max-height: 0;
  opacity: 0;
  transform: translateY(-6px);
  margin-top: 0;
  pointer-events: none;
}

.hero-chat-card__list {
  margin-top: 4px;
  min-height: 0;
  flex: 1 1 auto;
  overflow: auto;
  padding-right: 4px;
}

.hero-chat-card__list::-webkit-scrollbar {
  width: 10px;
}

.hero-chat-card__list::-webkit-scrollbar-track {
  border-radius: var(--scrollbar-radius);
  background: var(--scrollbar-track);
}

.hero-chat-card__list::-webkit-scrollbar-thumb {
  border-radius: var(--scrollbar-radius);
  border: 2px solid var(--scrollbar-thumb-border);
  background: var(--scrollbar-thumb);
}

.hero-chat-card__list::-webkit-scrollbar-thumb:hover {
  background: var(--scrollbar-thumb-hover);
}

.hero-chat-card__message + .hero-chat-card__message {
  margin-top: 4px;
}

.hero-chat-card__message {
  padding: 5px 9px;
  border-radius: 11px;
  border: 1px solid rgba(255, 255, 255, 0.1);
  background: rgba(255, 255, 255, 0.06);
}

.hero-chat-card__meta {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}

.hero-chat-card__meta strong {
  font-size: 0.76rem;
}

.hero-chat-card__meta span {
  color: rgba(245, 250, 244, 0.6);
  font-size: 0.66rem;
}

.hero-chat-card__meta-actions {
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

.hero-chat-card__delete {
  border: 1px solid rgba(255, 255, 255, 0.16);
  background: rgba(255, 255, 255, 0.08);
  color: rgba(255, 244, 244, 0.88);
  border-radius: 999px;
  padding: 1px 7px;
  font-size: 0.63rem;
  line-height: 1.4;
  cursor: pointer;
}

.hero-chat-card__delete:hover:not(:disabled) {
  background: rgba(188, 66, 66, 0.22);
  border-color: rgba(255, 140, 140, 0.36);
}

.hero-chat-card__delete:disabled {
  opacity: 0.55;
  cursor: default;
}

.hero-chat-card__text {
  margin-top: 2px;
  color: rgba(245, 250, 244, 0.92);
  font-size: 0.76rem;
  line-height: 1.25;
  white-space: pre-wrap;
  word-break: break-word;
}

.hero-chat-card__empty {
  min-height: 58px;
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  padding: 0 16px;
  border-radius: 14px;
  border: 1px dashed rgba(255, 255, 255, 0.16);
  color: rgba(245, 250, 244, 0.66);
  font-size: 0.76rem;
}

.hero-chat-card__composer {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-top: 4px;
}

.text-input.hero-chat-card__input {
  width: 100%;
  flex: 1 1 auto;
  max-width: none;
  height: 40px;
  min-height: 40px;
  min-width: 0;
  padding: 6px 12px;
  line-height: 1.2;
  font-size: 0.92rem;
  background: rgba(255, 252, 246, 0.94);
  border-radius: 14px;
}

.hero-chat-card__send {
  flex: 0 0 auto;
  width: auto;
  min-width: 58px;
  max-width: none;
  height: 34px;
  min-height: 34px;
  max-height: 34px;
  padding: 0;
  line-height: 1.2;
  border-radius: 10px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  white-space: nowrap;
  word-break: keep-all;
}

.hero-chat-card__hint {
  margin-top: 3px;
  color: rgba(245, 250, 244, 0.68);
  font-size: 0.66rem;
  line-height: 1.25;
}

.hero-chat-card__hint.is-error {
  color: #ffcbc0;
}

.hero-presence-card {
  position: absolute;
  right: 18px;
  bottom: 156px;
  z-index: 2;
  width: min(360px, calc(100vw - 36px));
  padding: 14px 16px;
  border-radius: 18px;
  color: #f5faf4;
  background: rgba(20, 44, 32, 0.8);
  border: 1px solid rgba(255, 255, 255, 0.2);
  box-shadow: 0 10px 24px rgba(12, 26, 19, 0.24);
  backdrop-filter: blur(6px);
}

.hero-presence-card__header,
.hero-gpu-guide__header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 10px;
}

.hero-panel-toggle {
  flex: 0 0 auto;
  min-width: 28px;
  min-height: 28px;
  padding: 0;
  border: 1px solid rgba(255, 255, 255, 0.14);
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.08);
  color: rgba(245, 250, 244, 0.86);
  font-size: 0.84rem;
  line-height: 1;
  cursor: pointer;
  transition: transform 220ms ease, background-color 160ms ease, border-color 160ms ease;
}

.hero-panel-toggle:hover {
  background: rgba(255, 255, 255, 0.12);
}

.hero-presence-card.is-collapsed .hero-panel-toggle,
.hero-gpu-guide.is-collapsed .hero-panel-toggle {
  transform: rotate(180deg);
}

.hero-presence-card__eyebrow {
  font-size: 0.76rem;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  opacity: 0.76;
}

.hero-presence-card__body,
.hero-gpu-guide__body {
  max-height: 360px;
  opacity: 1;
  transform: translateY(0);
  overflow: hidden;
  transition:
    max-height 280ms cubic-bezier(0.22, 1, 0.36, 1),
    opacity 180ms ease,
    transform 220ms ease,
    margin-top 220ms ease;
}

.hero-presence-card.is-collapsed .hero-presence-card__body,
.hero-gpu-guide.is-collapsed .hero-gpu-guide__body {
  max-height: 0;
  opacity: 0;
  transform: translateY(-6px);
  margin-top: 0;
  pointer-events: none;
}

.hero-presence-card__account {
  margin-top: 10px;
  padding: 10px 12px;
  border-radius: 14px;
  border: 1px solid rgba(255, 255, 255, 0.12);
  background: rgba(255, 255, 255, 0.06);
}

.hero-presence-card__account span {
  display: block;
  font-size: 0.74rem;
  color: rgba(245, 250, 244, 0.72);
}

.hero-presence-card__account strong {
  display: block;
  margin-top: 5px;
  font-size: 1rem;
}

.hero-presence-card__grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
  margin-top: 10px;
}

.hero-presence-card__grid div {
  padding: 12px 13px;
  border-radius: 14px;
  border: 1px solid rgba(255, 255, 255, 0.12);
  background: rgba(255, 255, 255, 0.07);
}

.hero-presence-card__grid span {
  display: block;
  font-size: 0.76rem;
  color: rgba(245, 250, 244, 0.72);
}

.hero-presence-card__grid strong {
  display: block;
  margin-top: 6px;
  font-size: 1.18rem;
  line-height: 1.28;
}

.hero-presence-card__wide {
  grid-column: 1 / -1;
}

.hero-presence-card__note {
  margin-top: 10px;
  color: rgba(245, 250, 244, 0.68);
  font-size: 0.78rem;
  line-height: 1.5;
}

.hero-presence-card__mobile-warning {
  display: none;
}

.hero-presence-card__actions {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  align-items: stretch;
  gap: 8px;
  margin-top: 12px;
}

.hero-presence-card__actions .button {
  width: 100%;
  min-width: 0;
  border-radius: 12px;
  justify-content: center;
  padding-inline: 8px;
  font-size: 0.84rem;
}

.hero-gpu-guide strong {
  display: block;
  font-size: 13.5px;
}

.hero-gpu-guide__body {
  margin-top: 6px;
}

.hero-gpu-guide__line + .hero-gpu-guide__line {
  margin-top: 4px;
}

.screen--setup {
  background:
    radial-gradient(circle at top right, rgba(208, 138, 47, 0.18), transparent 24%),
    linear-gradient(180deg, #f5ecdc 0%, #dbe5cc 100%);
}

.screen--burst-enter {
  position: relative;
  isolation: isolate;
  clip-path: circle(0px at var(--burst-x, 50vw) var(--burst-y, 50vh));
}

.screen--burst-enter-origin {
  transition: none;
}

.screen--burst-enter-small {
  clip-path: circle(40px at var(--burst-x, 50vw) var(--burst-y, 50vh));
  transition: clip-path 120ms ease-out;
}

.screen--burst-enter-full {
  clip-path: circle(var(--burst-final-radius, 160vmax) at var(--burst-x, 50vw) var(--burst-y, 50vh));
  transition: clip-path 700ms cubic-bezier(0.18, 0.02, 0.05, 1.2);
}

.menu-burst-ring {
  position: fixed;
  width: 28px;
  height: 28px;
  margin-left: -14px;
  margin-top: -14px;
  border-radius: 999px;
  border: 4px solid rgba(255, 250, 236, 0.92);
  box-shadow:
    0 0 0 2px rgba(64, 92, 67, 0.18),
    0 0 22px rgba(255, 244, 217, 0.55);
  pointer-events: none;
  z-index: 9000;
  opacity: 0;
}

.menu-burst-ring--pulse {
  animation: menu-burst-ring-pulse 280ms ease-out forwards;
}

@keyframes menu-burst-ring-pulse {
  0% {
    opacity: 0.96;
    transform: scale(0.78);
  }
  72% {
    opacity: 0.86;
    transform: scale(1.22);
  }
  100% {
    opacity: 0;
    transform: scale(1.52);
  }
}

.screen__glow {
  position: absolute;
  width: 620px;
  height: 520px;
  border-radius: 50%;
  filter: blur(12px);
  opacity: 0.5;
  pointer-events: none;
}

.screen__glow--left {
  top: -160px;
  left: -110px;
  background: radial-gradient(circle, rgba(109, 164, 91, 0.4), transparent 68%);
}

.screen__glow--right {
  right: -120px;
  bottom: -160px;
  background: radial-gradient(circle, rgba(208, 138, 47, 0.28), transparent 68%);
}

.hero-card,
.panel-card,
.panel {
  position: relative;
  z-index: 1;
}

.hero-card {
  width: min(960px, 100%);
  padding: 48px;
  border-radius: 32px;
  color: #fefbf4;
  background:
    linear-gradient(145deg, rgba(31, 73, 56, 0.95), rgba(51, 99, 64, 0.86)),
    linear-gradient(180deg, rgba(255, 255, 255, 0.06), transparent);
  box-shadow: 0 24px 60px rgba(22, 40, 30, 0.24);
  border: 1px solid rgba(255, 255, 255, 0.12);
}

.hero-card__eyebrow,
.section-heading__eyebrow,
.panel__eyebrow,
.topbar__eyebrow,
.weather-banner__eyebrow {
  display: inline-block;
  font-size: 0.76rem;
  font-weight: 700;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  opacity: 0.72;
}

.panel__eyebrow--ko {
  letter-spacing: 0.02em;
  text-transform: none;
}

.hero-card__title,
.section-heading h2,
.panel__header h2,
.topbar__title h1 {
  margin: 10px 0 0;
  font-family: 'Gowun Batang', serif;
  line-height: 1.05;
}

.hero-card__title {
  font-size: clamp(2.9rem, 5.2vw, 4.8rem);
  max-width: none;
  white-space: nowrap;
}

.hero-card__subtitle {
  max-width: 540px;
  margin: 16px 0 20px;
  color: rgba(255, 251, 244, 0.78);
  font-size: 1.05rem;
  line-height: 1.7;
}

.hero-card__stats,
.focus-hero__stats,
.option-grid,
.crop-grid,
.action-grid,
.meter-grid,
.info-grid,
.field-list,
.storage-list,
.log-list {
  display: grid;
  gap: 14px;
}

.hero-card__stats {
  grid-template-columns: repeat(3, minmax(0, 1fr));
  margin-bottom: 26px;
}

.hero-card__stats div,
.focus-hero__stats div,
.info-tile,
.summary-chip {
  padding: 16px 18px;
  border-radius: 20px;
  border: 1px solid rgba(255, 255, 255, 0.14);
  background: rgba(255, 255, 255, 0.08);
  backdrop-filter: blur(8px);
}

.hero-card__stats span,
.focus-hero__stats span,
.info-tile span,
.summary-chip span {
  display: block;
  font-size: 0.82rem;
  color: rgba(255, 251, 244, 0.74);
}

.hero-card__stats strong,
.focus-hero__stats strong,
.info-tile strong,
.summary-chip strong {
  display: block;
  margin-top: 6px;
  font-size: 1rem;
}

.dev-item-add-modal {
  width: min(1040px, calc(100vw - 48px));
  max-height: min(82vh, 920px);
  display: flex;
  flex-direction: column;
}

.dev-item-add-modal__toolbar {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
  margin-top: 14px;
}

.dev-item-add-modal__search {
  flex: 1 1 260px;
}

.dev-item-add-modal__presets {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 8px;
}

.dev-item-add-modal__tabs {
  margin-top: 12px;
}

.dev-item-add-grid {
  margin-top: 14px;
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
  gap: 12px;
  overflow-y: auto;
  padding-right: 4px;
}

.dev-item-add-card {
  min-height: 164px;
}

.dev-item-add-card__actions {
  flex-wrap: wrap;
}

.chip-money-amount {
  cursor: pointer;
}

.hero-card__actions,
.button-row,
.footer-actions,
.inline-summary,
.planting-toolbar {
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
}

.hero-bgm-panel {
  position: absolute;
  top: 10px;
  left: 10px;
  z-index: 2;
  width: min(222px, calc(100vw - 20px));
  padding: 7px 9px 8px;
  border-radius: 14px;
  border: 1px solid rgba(219, 240, 214, 0.2);
  color: #edf8e8;
  background: linear-gradient(180deg, rgba(101, 141, 102, 0.3), rgba(72, 109, 74, 0.26));
  box-shadow:
