.hero-card__actions .button {
  position: relative;
  overflow: hidden;
  border-radius: 14px;
  transition:
    transform 0.14s ease,
    box-shadow 0.14s ease,
    background-color 0.18s ease,
    border-color 0.18s ease,
    filter 0.14s ease;
}

.hero-card__actions .button::after {
  content: '';
  position: absolute;
  inset: 1px;
  border-radius: inherit;
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.16), rgba(255, 255, 255, 0));
  opacity: 0.72;
  pointer-events: none;
  transition: opacity 0.14s ease, transform 0.14s ease;
}

.button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 52px;
  padding: 12px 24px;
  border-radius: 18px;
  border: 1px solid rgba(40, 84, 63, 0.12);
  font-family: var(--font-ko-display);
  font-weight: 700;
  letter-spacing: -0.01em;
  position: relative;
  overflow: hidden;
  isolation: isolate;
  cursor: pointer;
  --button-fill-color-1: rgba(140, 225, 157, 0.24);
  --button-fill-color-2: rgba(140, 225, 157, 0);
  transition:
    transform 0.18s ease,
    box-shadow 0.18s ease,
    background-color 0.18s ease,
    border-color 0.18s ease,
    filter 0.16s ease;
}

.button::before {
  content: '';
  position: absolute;
  inset: 0;
  z-index: 0;
  border-radius: inherit;
  clip-path: inset(0 round inherit);
  background: linear-gradient(120deg, var(--button-fill-color-1), var(--button-fill-color-2));
  opacity: 0;
  transform: scaleX(0.2) translateX(-85%);
  transform-origin: left center;
  transition: opacity 0.2s ease, transform 0.35s ease;
  pointer-events: none;
}

.button > * {
  position: relative;
  z-index: 1;
}

.hero-chat-card .hero-chat-card__send {
  border-radius: 10px;
}

.button:hover,
.option-card:hover,
.field-card:hover,
.crop-card:hover,
.action-card:hover,
.storage-card:hover {
  transform: translateY(-1px);
}

.button:hover::before {
  opacity: 1;
  transform: scaleX(1.15) translateX(0);
}

.hero-card__actions .button:hover {
  transform: translateY(-2px);
  filter: brightness(1.02);
}

.hero-card__actions .button:focus-visible {
  outline: 2px solid rgba(248, 241, 224, 0.88);
  outline-offset: 3px;
}

.hero-card__actions .button:active {
  transform: translateY(2px) scale(0.985);
  filter: brightness(0.96);
}

.hero-card__actions .button:active::after {
  opacity: 0.34;
  transform: translateY(2px);
}

.button:disabled {
  opacity: 0.42;
  cursor: not-allowed;
  transform: none;
  box-shadow: none;
  filter: saturate(0.7);
}

.button:disabled::before {
  opacity: 0;
  transform: scaleX(0.2) translateX(-85%);
}

.disabled-tip {
  display: inline-flex;
