.day-transition-animate-button {
  position: relative;
  overflow: hidden;
  isolation: isolate;
  transition:
    transform 0.16s ease,
    box-shadow 0.16s ease,
    filter 0.14s ease;
}

.day-transition-animate-button::before {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(120deg, rgba(140, 225, 157, 0.24), rgba(140, 225, 157, 0));
  opacity: 0;
  transform: scaleX(0.2) translateX(-85%);
  transform-origin: left center;
  transition: opacity 0.2s ease, transform 0.35s ease;
  pointer-events: none;
}

.day-transition-animate-button::after {
  content: '';
  position: absolute;
  width: 34px;
  height: 34px;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(140, 225, 157, 0.5), rgba(140, 225, 157, 0));
  transform: translate(-50%, -50%) scale(0);
  opacity: 0;
  top: 50%;
  left: 50%;
  transition: transform 0.16s ease, opacity 0.16s ease;
  pointer-events: none;
}

.day-transition-animate-button:hover {
  transform: translateY(-1.5px);
  filter: brightness(1.02);
}

.day-transition-animate-button:hover::before {
  opacity: 1;
  transform: scaleX(1.15) translateX(0);
}

.day-transition-animate-button:active {
  transform: translateY(0.5px) scale(0.985);
}

.day-transition-animate-button:active::after {
  transform: scale(14);
  opacity: 0;
}

