.setup-difficulty-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(230px, 1fr));
  gap: 14px;
}

.setup-option-card {
  min-height: 122px;
}

.setup-option-card--with-image {
  padding: 16px 18px 18px;
}

.setup-vehicle-card__main {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 96px;
  align-items: start;
  gap: 16px;
}

.setup-vehicle-card__copy {
  min-width: 0;
}

.setup-option-card .option-card__row strong {
  flex: 1;
  min-width: 0;
}

.setup-option-card .option-card__row span {
  flex-shrink: 0;
}

.setup-option-card--starter-pack .option-card__row {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  justify-items: flex-start;
  align-items: start;
  gap: 6px;
}

.setup-option-card--starter-pack .option-card__row strong {
  width: 100%;
  white-space: normal;
  word-break: keep-all;
  overflow-wrap: anywhere;
  line-height: 1.32;
}

.setup-option-card--starter-pack .option-card__row span {
  white-space: nowrap;
}

.setup-option-card--difficulty {
  min-height: 236px;
  padding: 16px 16px 18px;
  background:
    linear-gradient(180deg, rgba(255, 254, 251, 0.98), rgba(246, 241, 232, 0.88)),
    radial-gradient(circle at top right, rgba(214, 226, 198, 0.16), transparent 28%);
}

.setup-option-card--difficulty.option-card--selected {
  box-shadow:
    0 18px 32px rgba(72, 110, 74, 0.16),
    inset 0 0 0 1px rgba(112, 160, 108, 0.22);
}

.setup-difficulty-card__topline {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  margin-bottom: 10px;
}

.setup-difficulty-indicator {
  display: inline-flex;
  align-items: center;
  padding: 6px 10px;
  border-radius: 999px;
  background: rgba(40, 84, 63, 0.08);
  color: var(--green-strong);
  font-size: 0.76rem;
  font-weight: 800;
  letter-spacing: 0.04em;
  margin-bottom: 10px;
}

.setup-difficulty-card__topline .setup-difficulty-indicator {
  margin-bottom: 0;
}

.setup-difficulty-card__stage {
  color: var(--ink-soft);
  font-size: 0.8rem;
  font-weight: 700;
  letter-spacing: 0.02em;
  word-break: keep-all;
}

.setup-difficulty-card__headline {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 12px;
}

.setup-difficulty-card__headline strong {
  color: var(--ink-strong);
  font-size: 1.55rem;
  line-height: 1;
  word-break: keep-all;
}

.setup-difficulty-card__headline span {
  color: var(--ink-strong);
  font-size: 0.98rem;
  font-weight: 800;
  flex-shrink: 0;
  word-break: keep-all;
}

.setup-difficulty-card__desc {
  min-height: 56px;
  line-height: 1.45;
  word-break: keep-all;
}

.setup-difficulty-card__facts {
  display: grid;
  gap: 8px;
  margin-top: 14px;
}

.setup-difficulty-card__fact {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: 10px 12px;
  border-radius: 14px;
  background: rgba(255, 255, 255, 0.62);
  border: 1px solid rgba(40, 84, 63, 0.08);
}

.setup-difficulty-card__fact span {
  color: var(--ink-soft);
  font-size: 0.8rem;
  font-weight: 700;
  word-break: keep-all;
}

.setup-difficulty-card__fact strong {
  color: var(--green-strong);
  font-size: 0.92rem;
  font-weight: 800;
  text-align: right;
  word-break: keep-all;
}

.setup-difficulty-card__risk {
  margin-top: 12px;
  color: var(--ink-soft);
  font-size: 0.84rem;
  line-height: 1.45;
  word-break: keep-all;
}

.setup-card-metrics {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 12px;
}

.setup-starter-price-stack {
  display: grid;
  gap: 8px;
  margin-top: 14px;
}

.setup-starter-price-stack__row {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}

.setup-starter-price-stack__label {
  font-size: 0.76rem;
  font-weight: 800;
  color: rgba(74, 93, 82, 0.72);
}

.setup-starter-price-stack__base {
  font-size: 0.98rem;
  font-weight: 800;
  color: rgba(96, 112, 102, 0.78);
  text-decoration: line-through;
  text-decoration-thickness: 2px;
  text-decoration-color: rgba(126, 92, 92, 0.72);
}

.setup-starter-price-stack__sale {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  align-items: start;
  gap: 4px;
  padding: 10px 14px;
  border-radius: 16px;
  background: linear-gradient(180deg, rgba(234, 245, 227, 0.96), rgba(220, 239, 210, 0.92));
  border: 1px solid rgba(104, 154, 94, 0.2);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.72),
    0 8px 16px rgba(46, 88, 52, 0.08);
}

.setup-starter-price-stack__sale span {
  display: block;
  font-size: 0.8rem;
  font-weight: 800;
  color: rgba(56, 95, 63, 0.78);
  white-space: nowrap;
  word-break: keep-all;
}

.setup-starter-price-stack__sale strong {
  display: block;
  font-size: 1.08rem;
  font-weight: 900;
  color: var(--green-strong);
  letter-spacing: -0.01em;
  min-width: 0;
  text-align: right;
  line-height: 1.2;
}

.setup-card-metrics span {
  display: inline-flex;
  align-items: center;
  min-height: 28px;
  padding: 0 10px;
  border-radius: 999px;
  background: rgba(40, 84, 63, 0.07);
  color: var(--green-strong);
  font-size: 0.8rem;
  font-weight: 700;
  line-height: 1.25;
  white-space: normal;
}

.setup-card-note {
  margin-top: 10px;
  color: var(--ink-soft);
  font-size: 0.84rem;
  line-height: 1.45;
}

.setup-vehicle-thumb {
  width: 96px;
  height: 96px;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 8px;
  border-radius: 18px;
  border: 1px solid rgba(40, 84, 63, 0.14);
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.96), rgba(245, 248, 242, 0.92)),
    radial-gradient(circle at top, rgba(204, 222, 196, 0.28), transparent 68%);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.72),
    0 10px 18px rgba(30, 48, 35, 0.08);
  pointer-events: none;
  overflow: hidden;
  align-self: start;
}

.setup-vehicle-thumb img {
  width: 100%;
  height: 100%;
  object-fit: contain;
  display: block;
  filter: drop-shadow(0 8px 10px rgba(30, 48, 35, 0.2));
}

.setup-section-card--vehicle {
  background:
    linear-gradient(180deg, rgba(247, 250, 244, 0.92), rgba(241, 246, 236, 0.72)),
    radial-gradient(circle at top right, rgba(181, 207, 171, 0.14), transparent 28%);
}

.setup-vehicle-grid {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}

.setup-selected-land-meter {
  background: rgba(255, 252, 246, 0.72);
  border-radius: 18px;
  border: 1px solid rgba(40, 84, 63, 0.08);
}

.setup-land-topline {
  align-items: stretch;
}

.land-select-overview {
  margin-top: 16px;
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(420px, 0.58fr);
  gap: 14px;
  align-items: stretch;
}

.land-select-overview__brief,
.land-select-overview__filters {
  border-radius: 24px;
  border: 1px solid rgba(40, 84, 63, 0.1);
  box-shadow: 0 14px 30px rgba(32, 48, 34, 0.06);
}

.land-select-overview__brief {
  padding: 18px 20px;
  background: linear-gradient(135deg, rgba(46, 88, 63, 0.96), rgba(86, 126, 86, 0.92));
  color: #fffaf0;
}

.land-select-overview__headline {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 12px;
}

.land-select-overview__headline span {
  color: rgba(255, 250, 240, 0.74);
  font-size: 0.8rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.land-select-overview__headline strong {
  font-size: 1.2rem;
}

.land-select-overview__chips {
  margin-top: 14px;
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 10px;
}

.land-select-overview__chip {
  min-height: 88px;
  padding: 12px 13px;
  border-radius: 18px;
  background: rgba(255, 250, 240, 0.12);
  border: 1px solid rgba(255, 250, 240, 0.12);
}

.land-select-overview__chip span {
  display: block;
  color: rgba(255, 250, 240, 0.66);
  font-size: 0.74rem;
}

.land-select-overview__chip strong {
  display: block;
  margin-top: 6px;
  font-size: 0.96rem;
  line-height: 1.35;
}

.land-select-overview__filters {
  padding: 18px 20px;
  background:
    linear-gradient(180deg, rgba(255, 254, 250, 0.96), rgba(247, 242, 233, 0.88)),
    radial-gradient(circle at top right, rgba(217, 228, 203, 0.18), transparent 30%);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
}

.land-select-overview__filter-note span {
  display: block;
  color: var(--ink-soft);
  font-size: 0.78rem;
}

.land-select-overview__filter-note strong {
  display: block;
  margin-top: 6px;
  color: var(--green-strong);
  font-size: 1.1rem;
}

.land-select-overview__filters .focus-tabs {
  flex: 0 0 auto;
  margin: 0;
  padding: 0;
  gap: 7px;
}

.land-select-overview__filters .focus-tab {
  min-height: 32px;
  padding: 6px 10px;
}

.land-select-layout {
  margin-top: 22px;
  display: grid;
  grid-template-columns: minmax(0, 1.5fr) minmax(320px, 0.82fr);
  gap: 20px;
  align-items: start;
}

.land-map-panel,
.land-side-panel {
  min-width: 0;
  border-radius: 30px;
  border: 1px solid rgba(53, 88, 65, 0.12);
  box-shadow: 0 20px 40px rgba(32, 48, 34, 0.08);
}

.land-map-panel {
  padding: 22px;
  background:
    linear-gradient(180deg, rgba(253, 251, 244, 0.98), rgba(244, 238, 224, 0.94)),
    radial-gradient(circle at top right, rgba(205, 219, 188, 0.28), transparent 30%);
}

.land-map-panel__head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 18px;
}

.land-map-panel__headline {
  max-width: 620px;
}

.land-map-panel__kicker {
  display: inline-block;
  color: rgba(39, 83, 59, 0.74);
  font-size: 0.76rem;
  font-weight: 800;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.land-map-panel__head h3 {
  margin: 10px 0 0;
  font-size: 1.6rem;
  line-height: 1.2;
  color: #244a34;
}

.land-map-panel__head p {
  margin: 10px 0 0;
  color: rgba(63, 73, 60, 0.9);
  font-size: 0.94rem;
  line-height: 1.65;
}

.land-map-panel__legend-card {
  min-width: 188px;
  padding: 14px 16px;
  border-radius: 20px;
  border: 1px solid rgba(58, 94, 69, 0.12);
  background: rgba(255, 252, 245, 0.82);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.7);
}

.land-map-panel__legend-title {
  margin-bottom: 8px;
  color: rgba(39, 83, 59, 0.76);
  font-size: 0.74rem;
  font-weight: 800;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.land-map-panel__legend {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-start;
  gap: 8px 12px;
  color: var(--ink-soft);
  font-size: 0.82rem;
}

.land-map-panel__legend span {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  white-space: nowrap;
}

.land-map-panel__legend-dot {
  width: 10px;
  height: 10px;
  border-radius: 999px;
  display: inline-block;
}

.land-map-panel__legend-dot--open {
  background: #507d57;
}

.land-map-panel__legend-dot--over {
  background: #b88663;
}

.land-map-panel__legend-dot--selected {
  background: #f7f0d2;
  box-shadow: 0 0 0 2px #2f6148 inset;
}

.land-map-panel__stats {
  margin-top: 14px;
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 10px;
}

.land-map-panel__stat {
  padding: 14px 16px;
  border-radius: 18px;
  border: 1px solid rgba(60, 95, 71, 0.1);
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.82), rgba(245, 240, 228, 0.76));
}

.land-map-panel__stat span {
  display: block;
  color: rgba(70, 76, 63, 0.72);
  font-size: 0.74rem;
}

.land-map-panel__stat strong {
  display: block;
  margin-top: 6px;
  color: #274c36;
  font-size: 1rem;
  line-height: 1.35;
}

.land-map-stage {
  position: relative;
  min-height: 500px;
  border-radius: 30px;
  overflow: hidden;
  overscroll-behavior: contain;
  border: 1px solid rgba(49, 86, 63, 0.16);
  background:
    linear-gradient(180deg, rgba(209, 225, 196, 0.96), rgba(177, 198, 158, 0.94) 46%, rgba(148, 171, 128, 0.96)),
    radial-gradient(circle at 20% 12%, rgba(255, 249, 230, 0.28), transparent 24%);
  touch-action: none;
  cursor: grab;
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.34),
    0 18px 30px rgba(50, 73, 48, 0.08);
}

.land-map-stage:active {
  cursor: grabbing;
}

.land-map-stage-wrap {
  margin-top: 18px;
}

.land-map-stage-controls {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 10px;
  margin-bottom: 12px;
  padding: 10px 12px;
  border-radius: 20px;
  background: rgba(255, 252, 244, 0.76);
  border: 1px solid rgba(48, 82, 60, 0.1);
}

.land-map-stage-controls__hint {
  color: rgba(67, 77, 63, 0.82);
  font-size: 0.8rem;
  font-weight: 700;
}

.land-map-stage-controls__actions {
  display: inline-flex;
  align-items: center;
  gap: 8px;
}

.land-map-stage-controls__zoom {
  min-width: 64px;
  padding: 8px 12px;
  border-radius: 999px;
  border: 1px solid rgba(40, 84, 63, 0.12);
  background: rgba(255, 255, 255, 0.86);
  color: #244a34;
  font-size: 0.84rem;
  font-weight: 800;
  text-align: center;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.7);
}

.land-map-stage__svg {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  pointer-events: none;
}

.land-map-stage__center-image {
  position: absolute;
  object-fit: fill;
  pointer-events: none;
  user-select: none;
  -webkit-user-drag: none;
  opacity: 0.82;
}

.land-map-stage__svg-base {
  fill: rgba(211, 225, 202, 0.9);
}

.land-map-stage__road {
  fill: none;
  stroke: rgba(129, 105, 82, 0.78);
  stroke-width: 1.35;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.land-map-stage__river {
  fill: none;
  stroke: rgba(96, 142, 165, 0.78);
  stroke-width: 1;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.land-map-stage__settlement text {
  fill: rgba(26, 49, 31, 0.9);
  font-size: 11px;
  font-weight: 800;
  text-anchor: middle;
  paint-order: stroke;
  stroke: rgba(252, 248, 239, 0.88);
  stroke-width: 3px;
  stroke-linejoin: round;
}

.land-map-stage__settlement-icon--village path {
  fill: rgba(111, 87, 64, 0.96);
}

.land-map-stage__settlement-icon--village rect {
  fill: rgba(93, 122, 84, 0.98);
}

.land-map-stage__settlement-icon--city rect:first-child {
  fill: rgba(126, 108, 160, 0.98);
}

.land-map-stage__settlement-icon--city rect:last-child {
  fill: rgba(101, 86, 134, 0.94);
}

.land-map-stage__backdrop {
  position: absolute;
  inset: 0;
  background:
    linear-gradient(180deg, rgba(250, 246, 236, 0.08), rgba(38, 62, 42, 0.11)),
    radial-gradient(circle at 14% 16%, rgba(255, 247, 222, 0.12), transparent 14%),
    radial-gradient(circle at 82% 24%, rgba(255, 247, 222, 0.1), transparent 18%);
  pointer-events: none;
}

.land-map-stage__corner-badge {
  position: absolute;
  top: 14px;
  left: 14px;
  z-index: 2;
  padding: 8px 12px;
  border-radius: 999px;
  background: rgba(255, 251, 242, 0.86);
  border: 1px solid rgba(45, 79, 57, 0.12);
  color: #2b543d;
  font-size: 0.78rem;
  font-weight: 800;
  box-shadow: 0 8px 18px rgba(34, 55, 38, 0.08);
  pointer-events: none;
}

.land-map-node {
  position: absolute;
  transform: translate(-50%, -50%);
  border-radius: 20px;
  border: 2px solid rgba(255, 251, 243, 0.72);
  box-shadow: 0 12px 22px rgba(36, 60, 42, 0.2);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  color: #fffaf0;
  font-size: 0.78rem;
  font-weight: 800;
  pointer-events: none;
  user-select: none;
  transition:
    transform 0.18s ease,
    box-shadow 0.18s ease,
    border-color 0.18s ease;
}

.land-map-node:hover {
  transform: translate(-50%, -50%) scale(1.08);
}

.land-map-stage.is-dragging {
  cursor: grabbing;
}

.land-map-stage.is-dragging .land-map-node {
  transition: none;
}

.land-map-stage.is-dragging .land-map-node:hover {
  transform: translate(-50%, -50%);
}

.land-map-node--open {
  background: linear-gradient(135deg, #436c4a 0%, #5b875d 100%);
}

.land-map-node--over {
  background: linear-gradient(135deg, #8f6a54 0%, #b28669 100%);
}

.land-map-node--selected {
  border-color: rgba(255, 248, 224, 0.96);
  box-shadow:
    0 0 0 4px rgba(255, 248, 224, 0.24),
    0 18px 30px rgba(36, 60, 42, 0.3);
}

.land-map-stage__footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  margin-top: 12px;
  padding: 12px 14px;
  border-radius: 18px;
  background: rgba(255, 250, 242, 0.7);
  border: 1px solid rgba(49, 84, 61, 0.08);
}

.land-map-stage__footer span {
  color: rgba(70, 76, 63, 0.78);
  font-size: 0.8rem;
  line-height: 1.45;
}

.land-map-stage__footer strong {
  color: #254b35;
  font-size: 0.9rem;
  white-space: nowrap;
}

.land-side-panel {
  padding: 20px;
  background:
    linear-gradient(180deg, rgba(255, 254, 250, 0.98), rgba(247, 242, 233, 0.92)),
    radial-gradient(circle at top right, rgba(217, 228, 203, 0.22), transparent 30%);
}

.land-side-panel__summary {
  padding: 20px 22px;
  border-radius: 24px;
  background:
    radial-gradient(circle at top right, rgba(255, 246, 210, 0.18), transparent 28%),
    linear-gradient(135deg, rgba(39, 79, 58, 0.98), rgba(78, 118, 84, 0.92));
  color: #fffaf0;
}

.land-side-panel__summary-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
}

.land-side-panel__summary span {
  display: block;
  color: rgba(255, 250, 240, 0.72);
  font-size: 0.78rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.land-side-panel__summary strong {
  display: block;
  margin-top: 10px;
  font-size: 1.22rem;
  line-height: 1.4;
  letter-spacing: -0.01em;
  word-break: keep-all;
}

.land-side-panel__summary p {
  margin: 10px 0 0;
  color: rgba(255, 250, 240, 0.86);
  font-size: 0.98rem;
  line-height: 1.6;
  word-break: keep-all;
}

.land-side-panel__status {
  display: inline-flex;
  align-items: center;
  min-height: 28px;
  padding: 0 11px;
  border-radius: 999px;
  font-size: 0.74rem;
  font-style: normal;
  font-weight: 800;
  letter-spacing: 0.04em;
}

.land-side-panel__status--open {
  background: rgba(226, 242, 216, 0.18);
  border: 1px solid rgba(232, 247, 223, 0.3);
  color: #eff8e9;
}

.land-side-panel__status--over {
  background: rgba(196, 130, 95, 0.22);
  border: 1px solid rgba(233, 194, 171, 0.26);
  color: #fff1e8;
}

.land-side-panel__detail {
  margin-top: 12px;
  padding: 18px;
  border-radius: 24px;
  border: 1px solid rgba(40, 84, 63, 0.1);
  background: rgba(255, 255, 255, 0.78);
}

.land-side-panel__money-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
}

.land-side-panel__money-card {
  padding: 14px 14px 15px;
  border-radius: 18px;
  background: linear-gradient(180deg, rgba(241, 248, 233, 0.94), rgba(251, 245, 232, 0.92));
  border: 1px solid rgba(73, 112, 79, 0.12);
  min-width: 0;
}

.land-side-panel__money-card--wide {
