  box-shadow:
    0 18px 42px rgba(32, 47, 36, 0.08),
    0 0 0 1px rgba(37, 82, 55, 0.05),
    inset 0 1px 0 rgba(255, 255, 255, 0.34),
    inset 0 -1px 0 rgba(37, 82, 55, 0.06);
  backdrop-filter: blur(5px);
