}

.weather-banner__rain-layer {
  position: absolute;
  inset: 0;
  z-index: 0;
  border-radius: inherit;
  pointer-events: none;
  overflow: hidden;
  opacity: 1;
  background:
    linear-gradient(180deg, rgba(235, 244, 250, 0.22), rgba(192, 211, 222, 0.1) 42%, rgba(66, 96, 113, 0.14)),
    radial-gradient(ellipse at 18% -8%, rgba(255, 255, 255, 0.28), transparent 36%),
    radial-gradient(ellipse at 84% 118%, rgba(91, 125, 139, 0.18), transparent 44%);
  background-size: auto, auto, auto;
}

.weather-banner__rain-layer::before,
.weather-banner__rain-layer::after {
  content: none;
}

.weather-banner__rain-drop {
  position: absolute;
  left: var(--rain-x);
  top: var(--rain-y);
  width: var(--rain-width);
  height: var(--rain-len);
  border-radius: 999px;
  background:
    linear-gradient(
      180deg,
      transparent 0%,
      rgba(var(--rain-head-color), calc(var(--rain-alpha) * 0.64)) 12%,
      rgba(var(--rain-color), var(--rain-alpha)) 48%,
      rgba(var(--rain-tail-color), calc(var(--rain-alpha) * 0.48)) 78%,
      transparent 100%
    );
  box-shadow:
    0 0 4px rgba(255, 255, 255, calc(var(--rain-alpha) * 0.22)),
    0 0 8px rgba(128, 174, 200, calc(var(--rain-alpha) * 0.12));
  opacity: 0;
  filter: blur(var(--rain-blur));
  transform: translate3d(0, -38px, 0) rotate(var(--rain-angle)) scaleY(0.16);
  transform-origin: 50% 0;
  animation: weather-banner-random-rain var(--rain-duration) linear infinite;
  animation-delay: var(--rain-delay);
  will-change: transform, opacity;
}

.weather-banner--rainy {
  background:
    linear-gradient(135deg, rgba(209, 226, 236, 0.46), rgba(147, 173, 188, 0.18) 34%, rgba(47, 82, 72, 0.1) 100%) border-box,
    radial-gradient(ellipse at 20% 0%, rgba(255, 255, 255, 0.34), transparent 38%),
    linear-gradient(180deg, rgba(236, 245, 248, 0.34), rgba(190, 210, 219, 0.2));
  border-color: rgba(217, 232, 237, 0.58);
  box-shadow:
    0 18px 46px rgba(24, 42, 52, 0.12),
    0 0 0 1px rgba(113, 145, 158, 0.12),
    inset 0 1px 0 rgba(255, 255, 255, 0.48),
    inset 0 -18px 34px rgba(54, 86, 101, 0.08);
}

.weather-banner--rainy::before,
.weather-banner--rainy::after {
  content: "";
  position: absolute;
  inset: 0;
  z-index: 0;
  border-radius: inherit;
  pointer-events: none;
}

.weather-banner--rainy::before {
  background:
    radial-gradient(circle at 8% 18%, rgba(255, 255, 255, 0.28) 0 1px, transparent 2px),
    radial-gradient(circle at 24% 62%, rgba(255, 255, 255, 0.2) 0 1px, transparent 2px),
    radial-gradient(circle at 43% 28%, rgba(62, 97, 116, 0.16) 0 1px, transparent 2px),
    radial-gradient(circle at 68% 54%, rgba(255, 255, 255, 0.24) 0 1px, transparent 2px),
    radial-gradient(circle at 88% 22%, rgba(60, 91, 111, 0.14) 0 1px, transparent 2px);
  background-size: 190px 130px, 260px 180px, 320px 210px, 230px 160px, 360px 220px;
  opacity: 0.55;
  filter: blur(0.15px);
  animation: weather-banner-droplet-slide 2800ms linear infinite;
}

.weather-banner--rainy::after {
  background:
    linear-gradient(180deg, transparent 0 54%, rgba(73, 103, 118, 0.08) 76%, rgba(27, 54, 67, 0.14) 100%),
    radial-gradient(ellipse at 28% 100%, rgba(255, 255, 255, 0.2), transparent 46%),
    radial-gradient(ellipse at 74% 104%, rgba(44, 78, 92, 0.16), transparent 42%);
  opacity: 0.72;
  animation: weather-banner-wet-breathe 2400ms ease-in-out infinite;
}

.weather-banner--rainy .weather-mini-grid {
  position: relative;
  z-index: 1;
}

.weather-banner--rainy .weather-mini-card.card-pinned {
  border: 1px solid rgba(222, 235, 237, 0.62) !important;
  background:
    linear-gradient(180deg, rgba(246, 250, 248, 0.52), rgba(216, 229, 226, 0.34)),
    radial-gradient(ellipse at 50% -8%, rgba(255, 255, 255, 0.52), transparent 58%) !important;
  box-shadow:
    0 12px 28px rgba(31, 55, 64, 0.1),
    inset 0 1px 0 rgba(255, 255, 255, 0.7),
    inset 0 -16px 28px rgba(84, 112, 121, 0.08) !important;
  backdrop-filter: blur(12px) saturate(0.92);
  -webkit-backdrop-filter: blur(12px) saturate(0.92);
}

.weather-banner--rainy .weather-mini-card.card-pinned::after {
  inset: 1px;
  border-color: rgba(255, 255, 255, 0.28);
  border-radius: 20px;
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.28),
    inset 0 -1px 0 rgba(60, 89, 101, 0.08);
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.16), transparent 36%),
    radial-gradient(ellipse at 16% 0%, rgba(255, 255, 255, 0.18), transparent 34%);
  animation: weather-banner-card-sheen 3600ms ease-in-out infinite;
}

.weather-banner--rainy .weather-mini-card__label,
.weather-banner--rainy .weather-mini-card__desc {
