}

.weather-banner--rainy .weather-mini-card__value,
.weather-banner--rainy .weather-mini-card--temp .weather-mini-card__value,
.weather-banner--rainy .weather-mini-card--today .weather-mini-card__value {
  color: #214f43;
  text-shadow: 0 1px 0 rgba(255, 255, 255, 0.5);
}

@keyframes weather-banner-random-rain {
  0% {
    opacity: 0;
    transform: translate3d(0, -48px, 0) rotate(var(--rain-angle)) scaleY(0.12);
  }
  12% {
    opacity: calc(var(--rain-alpha) * 0.45);
    transform: translate3d(var(--rain-sway), -18px, 0) rotate(var(--rain-angle)) scaleY(0.48);
  }
  38% {
    opacity: var(--rain-alpha);
    transform: translate3d(0, 58px, 0) rotate(var(--rain-angle)) scaleY(1);
  }
  74% {
    opacity: calc(var(--rain-alpha) * 0.46);
    transform: translate3d(calc(var(--rain-sway) * -0.6), 144px, 0) rotate(var(--rain-angle)) scaleY(0.5);
  }
  100% {
    opacity: 0;
    transform: translate3d(0, 198px, 0) rotate(var(--rain-angle)) scaleY(0.08);
  }
}

@keyframes weather-banner-droplet-slide {
  from {
    transform: translate3d(0, -42px, 0);
  }
  to {
    transform: translate3d(0, 96px, 0);
  }
}

@keyframes weather-banner-wet-breathe {
  0%,
  100% {
    opacity: 0.58;
    filter: saturate(0.94);
  }
  50% {
    opacity: 0.78;
    filter: saturate(1.02);
  }
}

@keyframes weather-banner-card-sheen {
  0%,
  100% {
    opacity: 0.58;
  }
  48% {
    opacity: 0.86;
  }
}
