.slot-roll {
  position: relative;
  display: inline-grid;
  align-items: center;
  overflow: hidden;
  min-height: 1.2em;
  vertical-align: top;
}

.slot-roll__ghost {
  visibility: hidden;
  grid-area: 1 / 1;
}

.slot-roll__layer {
  grid-area: 1 / 1;
  display: inline-block;
  transform: translateY(0);
  opacity: 1;
  transition:
    transform var(--slot-roll-duration, 560ms) cubic-bezier(0.16, 0.84, 0.24, 1),
    opacity var(--slot-roll-duration, 560ms) ease;
  white-space: nowrap;
}

.slot-roll__layer--next {
  transform: translateY(-105%);
  opacity: 0;
}

.slot-roll.is-running .slot-roll__layer--prev {
  transform: translateY(105%);
  opacity: 0;
}

.slot-roll.is-running .slot-roll__layer--next {
  transform: translateY(0);
  opacity: 1;
}

.slot-roll:not(.is-running) .slot-roll__layer--next {
  transform: translateY(0);
  opacity: 1;
}

