.meter--task {
  --task-bg: linear-gradient(180deg, rgba(255, 255, 255, 0.76), rgba(250, 246, 237, 0.66));
  --task-border: rgba(40, 84, 63, 0.12);
  --task-chip-bg: rgba(255, 255, 255, 0.78);
  --task-chip-border: rgba(40, 84, 63, 0.16);
  --task-chip-color: var(--green-strong);
  --task-title-color: var(--ink);
  display: flex;
  flex-direction: column;
  min-height: 274px;
  border-color: var(--task-border);
  background: var(--task-bg);
  box-shadow: 0 4px 14px rgba(35, 45, 33, 0.05);
}

.meter--task > .meter + .meter {
  margin-top: 10px;
}

.meter__top {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 8px;
  font-size: 0.9rem;
  font-weight: 700;
  color: var(--ink-soft);
}

.meter__top-actions {
  display: inline-flex;
  align-items: center;
  gap: 8px;
}

.meter__action-toggle {
  width: 24px;
  height: 24px;
  border-radius: 7px;
}

.meter__action-panel {
  overflow: hidden;
}

.meter__action-panel--collapsible {
  max-height: 120px;
  opacity: 1;
  transform: translateY(0);
  transform-origin: top;
  transition:
    max-height 320ms cubic-bezier(0.22, 1, 0.36, 1),
    opacity 180ms ease,
    transform 240ms ease;
}

.meter__action-panel--collapsible.is-collapsed {
  max-height: 0;
  opacity: 0;
  transform: translateY(-6px);
  pointer-events: none;
}

.meter__action-panel-inner {
  margin-top: 14px;
}

.meter--collapsible.meter--collapsed {
  min-height: 0;
}

.meter--task.meter--collapsible.meter--collapsed {
  min-height: 0 !important;
  padding-top: 12px;
  padding-bottom: 12px;
}

.meter--collapsible {
  overflow: hidden;
  transition:
    min-height 320ms cubic-bezier(0.22, 1, 0.36, 1),
    box-shadow 220ms ease,
    border-color 220ms ease,
    background-color 220ms ease;
}

.meter--collapsible > :not(.meter__top) {
  max-height: 1200px;
  opacity: 1;
  overflow: hidden;
  transform: translateY(0);
  transform-origin: top;
  transition:
    max-height 360ms cubic-bezier(0.22, 1, 0.36, 1),
    opacity 180ms ease,
    transform 240ms ease,
    margin-top 360ms cubic-bezier(0.22, 1, 0.36, 1);
}

.meter-grid--uniform .meter--collapsible:not(.meter--collapsed) {
  animation: meter-expand-card-in 360ms cubic-bezier(0.22, 1, 0.36, 1) both;
}

.meter-grid--uniform .meter--collapsible:not(.meter--collapsed) > :not(.meter__top) {
  animation: meter-expand-content-in 420ms cubic-bezier(0.18, 0.9, 0.2, 1) both;
}

.meter-grid--uniform .meter--collapsible:not(.meter--collapsed):nth-child(1) { animation-delay: 0ms; }
.meter-grid--uniform .meter--collapsible:not(.meter--collapsed):nth-child(2) { animation-delay: 25ms; }
.meter-grid--uniform .meter--collapsible:not(.meter--collapsed):nth-child(3) { animation-delay: 50ms; }
.meter-grid--uniform .meter--collapsible:not(.meter--collapsed):nth-child(4) { animation-delay: 75ms; }
.meter-grid--uniform .meter--collapsible:not(.meter--collapsed):nth-child(5) { animation-delay: 100ms; }
.meter-grid--uniform .meter--collapsible:not(.meter--collapsed):nth-child(6) { animation-delay: 125ms; }
.meter-grid--uniform .meter--collapsible:not(.meter--collapsed):nth-child(7) { animation-delay: 150ms; }
.meter-grid--uniform .meter--collapsible:not(.meter--collapsed):nth-child(8) { animation-delay: 175ms; }

.meter-grid--uniform .meter--collapsible:not(.meter--collapsed):nth-child(1) > :not(.meter__top) { animation-delay: 35ms; }
.meter-grid--uniform .meter--collapsible:not(.meter--collapsed):nth-child(2) > :not(.meter__top) { animation-delay: 60ms; }
.meter-grid--uniform .meter--collapsible:not(.meter--collapsed):nth-child(3) > :not(.meter__top) { animation-delay: 85ms; }
.meter-grid--uniform .meter--collapsible:not(.meter--collapsed):nth-child(4) > :not(.meter__top) { animation-delay: 110ms; }
.meter-grid--uniform .meter--collapsible:not(.meter--collapsed):nth-child(5) > :not(.meter__top) { animation-delay: 135ms; }
.meter-grid--uniform .meter--collapsible:not(.meter--collapsed):nth-child(6) > :not(.meter__top) { animation-delay: 160ms; }
.meter-grid--uniform .meter--collapsible:not(.meter--collapsed):nth-child(7) > :not(.meter__top) { animation-delay: 185ms; }
.meter-grid--uniform .meter--collapsible:not(.meter--collapsed):nth-child(8) > :not(.meter__top) { animation-delay: 210ms; }

.meter--collapsible.meter--collapsed > :not(.meter__top) {
  max-height: 0;
  min-height: 0 !important;
  opacity: 0;
  transform: translateY(-6px);
  margin-top: 0 !important;
  margin-bottom: 0 !important;
  padding-top: 0 !important;
  padding-bottom: 0 !important;
  border-top-width: 0 !important;
  border-bottom-width: 0 !important;
  pointer-events: none;
}

@keyframes meter-expand-card-in {
  from {
    opacity: 0.86;
    transform: translateY(-8px) scale(0.985);
    filter: saturate(0.92);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1);
    filter: saturate(1);
  }
}

@keyframes meter-expand-content-in {
  from {
    opacity: 0;
    transform: translateY(-10px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@media (prefers-reduced-motion: reduce) {
  .meter-grid--uniform .meter--collapsible:not(.meter--collapsed),
  .meter-grid--uniform .meter--collapsible:not(.meter--collapsed) > :not(.meter__top) {
    animation: none;
  }
}

