  min-height: 20px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.harvest-plan-worker-chip__equip-icon {
  width: 19px;
  height: 19px;
  border-radius: 5px;
  background: rgba(240, 248, 243, 0.92);
  border: 1px solid rgba(40, 84, 63, 0.14);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  box-shadow: 0 2px 5px rgba(25, 74, 57, 0.08);
}

.harvest-plan-worker-chip__equip-icon.is-selected {
  background: linear-gradient(180deg, rgba(236, 250, 241, 0.98), rgba(205, 233, 217, 0.98));
  border-color: rgba(31, 103, 73, 0.3);
  box-shadow: 0 0 0 3px rgba(44, 121, 87, 0.14), 0 6px 12px rgba(25, 74, 57, 0.12);
}

.harvest-plan-worker-chip__equip-icon img {
  width: 92%;
  height: 92%;
  object-fit: contain;
}

.harvest-plan-worker-chip__equip-badge {
  max-width: 54px;
  padding: 1px 4px;
  border-radius: 999px;
  background: rgba(27, 74, 57, 0.12);
  color: rgba(27, 74, 57, 0.86);
  font-size: 9px;
  font-weight: 800;
  line-height: 1.2;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.harvest-plan-worker-chip__labor {
  font-size: 11px;
  font-weight: 800;
  line-height: 1;
  color: rgba(27, 74, 57, 0.72);
}

.harvest-plan-worker-chip--day-locked {
  border-color: rgba(196, 74, 53, 0.22);
}

.crew-status-worker-chip {
  min-height: 136px;
  gap: 6px;
}

.crew-status-worker-chip__icon {
  font-size: 30px;
}

.crew-status-worker-chip__period {
  min-height: auto;
  font-size: 11px;
  font-weight: 700;
  line-height: 1.1;
  color: rgba(27, 74, 57, 0.82);
  white-space: nowrap;
}

.harvest-plan-worker-chip--droppable {
  cursor: pointer;
}

.harvest-plan-worker-chip--locked {
  opacity: 0.66;
}

.harvest-plan-worker-chip--drop-invalid {
  opacity: 1;
  border-color: rgba(197, 63, 63, 0.58) !important;
  background:
    linear-gradient(180deg, rgba(255, 247, 247, 0.98), rgba(255, 235, 235, 0.96)) !important;
  box-shadow:
    0 10px 22px rgba(175, 46, 46, 0.14),
    inset 0 0 0 1px rgba(214, 92, 92, 0.18) !important;
}

.harvest-plan-worker-chip__drop-reason {
  position: absolute;
  left: 50%;
  bottom: calc(100% + 6px);
  transform: translateX(-50%);
  z-index: 2;
  min-width: 96px;
  max-width: 132px;
  padding: 6px 8px;
  border-radius: 10px;
  border: 1px solid rgba(201, 82, 82, 0.34);
  background: rgba(255, 247, 247, 0.98);
  box-shadow: 0 8px 18px rgba(175, 46, 46, 0.14);
  font-size: 11px;
  line-height: 1.25;
  font-weight: 700;
  color: #b63b3b;
  text-align: center;
  word-break: keep-all;
  white-space: normal;
  pointer-events: none;
}

.harvest-plan-worker-chip__drop-reason::after {
  content: '';
  position: absolute;
  left: 50%;
  top: 100%;
  width: 10px;
  height: 10px;
  background: rgba(255, 247, 247, 0.98);
  border-right: 1px solid rgba(201, 82, 82, 0.34);
  border-bottom: 1px solid rgba(201, 82, 82, 0.34);
  transform: translate(-50%, -5px) rotate(45deg);
}

.harvest-plan-assignment-grid {
  margin-top: 12px;
  display: grid;
  gap: 10px;
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  padding-right: 4px;
  align-content: start;
}

.harvest-plan-assignment-card {
  border-radius: 18px;
  border: 1px solid rgba(40, 84, 63, 0.18);
  background: rgba(255, 255, 255, 0.9);
  box-shadow: 0 8px 18px rgba(25, 74, 57, 0.08);
  padding: 12px 14px;
  display: grid;
  gap: 10px;
  color: #1b4a39;
  cursor: grab;
  user-select: none;
  transform-origin: center center;
  transition:
    transform 180ms cubic-bezier(0.2, 0.9, 0.2, 1),
    box-shadow 180ms ease,
    border-color 180ms ease,
    background 180ms ease;
}

.harvest-plan-assignment-card__main {
  display: grid;
  grid-template-columns: 72px minmax(0, 1fr);
  align-items: center;
  gap: 12px;
}

.harvest-plan-assignment-card--with-fuel {
  padding-bottom: 10px;
}

.harvest-plan-assignment-card:active {
  cursor: grabbing;
}

.harvest-plan-assignment-card--pressed {
  transform: scale(0.98);
  border-color: rgba(84, 146, 109, 0.72);
  box-shadow: 0 0 0 2px rgba(52, 112, 82, 0.24), 0 16px 30px rgba(25, 74, 57, 0.16);
}

.harvest-plan-assignment-card--dragging {
  transform: scale(1.03);
  box-shadow: 0 18px 32px rgba(25, 74, 57, 0.18);
  border-color: rgba(43, 112, 81, 0.22);
  background: rgba(255, 255, 255, 0.9);
}

.harvest-plan-assignment-card__thumb {
  width: 72px;
  height: 72px;
  border-radius: 16px;
  border: 1px solid rgba(46, 104, 79, 0.14);
  background: linear-gradient(180deg, rgba(242, 249, 245, 0.96), rgba(228, 240, 233, 0.96));
  display: grid;
  place-items: start center;
  overflow: hidden;
  transition: transform 180ms cubic-bezier(0.2, 0.9, 0.2, 1), box-shadow 180ms ease;
}

.harvest-plan-assignment-card__thumb img {
  width: 88%;
  height: 88%;
  object-fit: contain;
  object-position: top center;
  pointer-events: none;
}

.harvest-plan-assignment-card__thumb--basket img {
  width: 90%;
  height: 90%;
  object-position: center -12px;
}

.harvest-plan-assignment-card__thumb--ladder img {
  width: 96%;
  height: 96%;
  object-position: center 14px;
}

.harvest-plan-assignment-card--pressed .harvest-plan-assignment-card__thumb {
  transform: scale(0.98);
}

.harvest-plan-assignment-card--dragging .harvest-plan-assignment-card__thumb {
  transform: scale(1.04);
  box-shadow: 0 10px 18px rgba(25, 74, 57, 0.12);
}

.harvest-plan-assignment-card__body {
  min-width: 0;
  display: grid;
  gap: 5px;
}

.harvest-plan-assignment-card strong {
  font-size: 14px;
}

.harvest-plan-assignment-card span,
.harvest-plan-assignment-card small {
  font-size: 12px;
  color: rgba(27, 74, 57, 0.76);
}

.harvest-plan-assignment-card--assigned {
  border-color: rgba(46, 111, 81, 0.34);
  background: linear-gradient(180deg, rgba(237, 246, 241, 0.94), rgba(221, 238, 229, 0.94));
}

.harvest-plan-assignment-card__fuel {
  margin: 0;
}

@keyframes harvest-assignment-card-float {
  0% {
    transform: scale(1.03) rotate(-1deg);
  }
  50% {
    transform: scale(1.05) rotate(1deg);
  }
  100% {
    transform: scale(1.03) rotate(-1deg);
  }
}

@keyframes app-icon-wiggle {
  0% {
    transform: scale(1.02) rotate(0deg);
  }
  25% {
    transform: scale(1.02) rotate(-1.2deg);
  }
  50% {
    transform: scale(1.02) rotate(1.2deg);
  }
  75% {
    transform: scale(1.02) rotate(-0.8deg);
  }
  100% {
    transform: scale(1.02) rotate(0deg);
  }
}

.harvest-plan-labor-check {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: 14px;
  color: #194a39;
}

.arrival-roster {
  display: grid;
  gap: 12px;
}

.crew-widget--clickable {
  cursor: pointer;
}

.crew-widget--clickable:focus-visible {
  outline: 2px solid rgba(46, 111, 81, 0.35);
  outline-offset: 3px;
}

.confirm-modal--crew-status {
