}

.confirm-modal--crew-status .harvest-plan-worker-chip.is-selected,
.confirm-modal--crew-status .slot-button-card.is-selected {
  background: linear-gradient(180deg, rgba(233, 246, 239, 0.98), rgba(216, 236, 226, 0.94));
  border-width: 2px;
  border-color: #2b704f;
  box-shadow: 0 4px 10px rgba(49, 112, 80, 0.12);
  color: #0c3527;
  transform: none;
}

.confirm-modal--crew-status .harvest-plan-worker-chip.is-selected strong,
.confirm-modal--crew-status .harvest-plan-worker-chip.is-selected span,
.confirm-modal--crew-status .slot-button-card.is-selected strong,
.confirm-modal--crew-status .slot-button-card.is-selected span {
  color: #0c3527;
}

.crew-status-modal__body {
  margin-top: 12px;
  padding-right: 4px;
  flex: 1 1 auto;
  min-height: 0;
  overflow-y: auto;
}

.crew-status-modal__summary {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  margin-top: 12px;
}

.arrival-roster__group {
  display: grid;
  gap: 8px;
}

.arrival-roster__title {
  font-size: 15px;
  font-weight: 800;
