}

.arrival-roster__list {
  display: grid;
  gap: 6px;
  padding-left: 4px;
}

.arrival-roster__item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  font-size: 14px;
  color: rgba(27, 74, 57, 0.86);
}

.arrival-roster__item--detail {
  align-items: flex-start;
}

.arrival-roster__copy {
  display: grid;
  gap: 2px;
}

.arrival-roster__copy small {
  font-size: 12px;
  color: rgba(27, 74, 57, 0.62);
}

.arrival-roster__item strong {
  font-size: 13px;
  color: rgba(27, 74, 57, 0.72);
}

.harvest-plan-labor-check > input {
  width: 16px;
  height: 16px;
}

@media (max-width: 900px) {
  .harvest-plan-modal-cluster {
    width: min(980px, calc(100vw - 24px));
