  }

  .harvest-plan-labor-row {
    grid-template-columns: 1fr;
  }

  .harvest-plan-topbar__crop {
    width: 100%;
  }

  .harvest-plan-editor {
    grid-template-columns: 1fr;
  }

  .harvest-plan-inline-slider-panel {
    grid-template-columns: 1fr;
  }

  .harvest-plan-dual-modal-wrap {
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    align-items: flex-start;
    overflow-y: auto;
