.confirm-modal--growth-image-preview {
  width: min(940px, calc(100vw - 28px));
  max-height: calc(100vh - 20px);
  overflow-y: auto;
}

.growth-image-preview {
  margin-top: 10px;
  border-radius: 14px;
  border: 1px solid rgba(40, 84, 63, 0.2);
  background: rgba(240, 248, 241, 0.86);
  padding: 10px;
}

.growth-image-preview__image {
  display: block;
  width: 100%;
  max-height: min(68vh, 620px);
  object-fit: contain;
  object-position: center center;
  border-radius: 10px;
}

.pest-diagnosis-summary {
  width: min(560px, 100%);
  margin: 0 auto;
}

.pest-diagnosis-columns {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
}

.groundwater-modal {
  margin-top: 8px;
  display: grid;
  grid-template-columns: minmax(460px, 1.15fr) minmax(260px, 1fr);
  gap: 16px;
}

.groundwater-modal__visual {
  border-radius: 16px;
  border: 1px solid rgba(40, 84, 63, 0.16);
  background: linear-gradient(180deg, #f3f9ff 0%, #e8f4e8 28%, #d2ebc4 100%);
  padding: 16px;
}

.groundwater-scene {
  width: min(100%, 520px);
  height: 500px;
  margin: 0 auto;
  position: relative;
}

.groundwater-scene__label {
  position: absolute;
  top: 20px;
  right: 16px;
  z-index: 5;
  background: rgba(255, 255, 255, 0.93);
  border-radius: 14px;
  padding: 10px 14px;
  min-width: 110px;
  text-align: center;
  box-shadow: 0 8px 18px rgba(0, 0, 0, 0.12);
}

.groundwater-scene__label-title {
  font-size: 13px;
  color: #3d4954;
}

.groundwater-scene__label-value {
  margin-top: 3px;
  font-size: 28px;
  line-height: 1;
  font-weight: 800;
  color: #167abf;
}

.groundwater-scene__ground-top {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 108px;
  border-radius: 18px 18px 0 0;
  background: linear-gradient(to bottom, #67bc59 0%, #54a34b 100%);
  overflow: hidden;
  z-index: 3;
}

.groundwater-scene__tree {
  position: absolute;
  bottom: 14px;
  width: 46px;
  height: 72px;
}

.groundwater-scene__tree--left {
  left: 56px;
}

.groundwater-scene__tree--right {
  right: 56px;
  transform: scale(0.92);
}

.groundwater-scene__leaf {
  position: absolute;
  left: 0;
  top: 0;
  width: 46px;
  height: 46px;
  border-radius: 50%;
  background: #3ea24d;
  box-shadow:
    -10px 8px 0 0 #4cb45d,
    10px 8px 0 0 #2f9340;
}

.groundwater-scene__trunk {
  position: absolute;
  left: 18px;
  bottom: 0;
  width: 10px;
  height: 29px;
  border-radius: 4px;
  background: #7a4b28;
}

.groundwater-scene__soil {
  position: absolute;
  top: 88px;
  left: 0;
  width: 100%;
  height: 412px;
  border-radius: 0 0 22px 22px;
  overflow: hidden;
  background: linear-gradient(to bottom, #996944 0%, #7a4d2f 46%, #5c3821 100%);
  box-shadow: inset 0 0 18px rgba(0, 0, 0, 0.24);
}

.groundwater-scene__soil::before {
  content: "";
  position: absolute;
  inset: 0;
  background-image:
    radial-gradient(circle at 20% 20%, rgba(255, 255, 255, 0.08) 2px, transparent 3px),
    radial-gradient(circle at 60% 40%, rgba(0, 0, 0, 0.12) 2px, transparent 3px),
    radial-gradient(circle at 35% 74%, rgba(255, 255, 255, 0.05) 2px, transparent 3px),
    radial-gradient(circle at 80% 68%, rgba(0, 0, 0, 0.1) 2px, transparent 3px);
  background-size: 92px 92px;
  opacity: 0.8;
}

.groundwater-scene__water {
  position: absolute;
  left: 0;
  bottom: 0;
  width: 100%;
  min-height: 6%;
  transition: height 0.8s ease;
  background: linear-gradient(to top, rgba(49, 176, 255, 0.86), rgba(114, 216, 255, 0.66));
  overflow: hidden;
  z-index: 2;
}

.groundwater-scene__wave {
  position: absolute;
  top: -16px;
  left: 0;
  width: 200%;
  height: 40px;
  background: rgba(255, 255, 255, 0.35);
  border-radius: 42%;
  animation: groundwaterWaveMove 7s linear infinite;
}

.groundwater-scene__wave--sub {
  top: -10px;
  opacity: 0.45;
  height: 46px;
  animation-duration: 10s;
  animation-direction: reverse;
}

.groundwater-scene__bubble {
  position: absolute;
  bottom: -18px;
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.45);
  animation: groundwaterBubbleRise 4.2s infinite ease-in;
}

.groundwater-scene__bubble--1 {
  left: 14%;
  animation-delay: 0s;
}

.groundwater-scene__bubble--2 {
  left: 35%;
  animation-delay: 1.1s;
}

.groundwater-scene__bubble--3 {
  left: 57%;
  animation-delay: 0.45s;
}

.groundwater-scene__bubble--4 {
  left: 78%;
  animation-delay: 1.8s;
}

.groundwater-modal__metrics {
  display: grid;
  gap: 10px;
  align-content: start;
}

.groundwater-modal__metric {
  border-radius: 14px;
  border: 1px solid rgba(40, 84, 63, 0.14);
  background: rgba(255, 255, 255, 0.68);
  padding: 12px 14px;
  display: grid;
  gap: 4px;
}

.groundwater-modal__metric span {
  font-size: 13px;
  color: #4a5a56;
}

.groundwater-modal__metric strong {
  font-size: 19px;
  color: #1f4f3f;
}

@keyframes groundwaterWaveMove {
  from {
    transform: translateX(0);
  }
  to {
    transform: translateX(-25%);
  }
}

@keyframes groundwaterBubbleRise {
  0% {
    transform: translateY(0) scale(0.82);
    opacity: 0;
  }
  20% {
    opacity: 0.82;
  }
  100% {
    transform: translateY(-178px) scale(1.2);
    opacity: 0;
  }
}

.animation-lab {
