.animation-lab__editor {
  width: 100%;
  min-height: 0;
  height: 100%;
  resize: vertical;
  font-family: 'Consolas', 'Pretendard', monospace;
  font-size: 0.92rem;
  line-height: 1.5;
  white-space: pre;
  overflow: auto;
}

.animation-lab__preview-wrap {
  position: relative;
  min-height: 0;
  height: 100%;
  border-radius: 16px;
  border: 1px solid rgba(40, 84, 63, 0.16);
  background: rgba(255, 255, 255, 0.5);
  overflow: auto;
}

.animation-lab__preview-resize-handle {
  position: absolute;
  left: -9px;
  top: 0;
  bottom: 0;
  width: 18px;
  padding: 0;
  border: 0;
  background: transparent;
  cursor: col-resize;
  z-index: 4;
}

.animation-lab__preview-resize-handle::before {
  content: "";
  position: absolute;
  left: 8px;
  top: 18px;
  bottom: 18px;
  width: 2px;
  border-radius: 999px;
  background: rgba(76, 123, 94, 0.18);
  transition: background-color 0.18s ease, box-shadow 0.18s ease;
}

.animation-lab__preview-resize-handle:hover::before,
.animation-lab__preview-resize-handle:focus-visible::before {
  background: rgba(76, 123, 94, 0.52);
  box-shadow: 0 0 0 4px rgba(76, 123, 94, 0.12);
}

body.is-resizing-animation-lab-preview,
body.is-resizing-animation-lab-preview * {
  cursor: col-resize !important;
  user-select: none !important;
}

.animation-lab__preview {
  width: 100%;
  height: 100%;
  min-height: 0;
  border: 0;
  background: #ffffff;
}

.animation-lab__preview--map-only {
  min-height: 0;
  background: transparent;
}

.animation-lab__layer-overlay {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  pointer-events: none;
}

.animation-lab__layer-overlay.is-enabled {
  pointer-events: auto;
}

.animation-lab__toolbar .button.is-active {
  border-color: rgba(255, 109, 58, 0.55);
  background: rgba(255, 109, 58, 0.14);
  color: #8e381f;
}

.animation-lab__layer-line-hit {
  cursor: move;
}

.animation-lab__layer-line {
  pointer-events: auto;
  cursor: move;
  stroke-linecap: round;
}

.animation-lab__layer-line.is-selected {
  filter: drop-shadow(0 0 2px rgba(255, 255, 255, 0.9));
}

.animation-lab__layer-handle {
  pointer-events: auto;
  fill: #ffffff;
  stroke: rgba(26, 26, 26, 0.78);
  stroke-width: 2px;
  cursor: pointer;
}

.animation-lab__layer-handle.is-selected {
  fill: #fff3e8;
  stroke: #ff6d3a;
}

