  background: radial-gradient(circle at 36% 28%, #ff9584, #df4735 45%, #a6241b 100%);
  box-shadow:
    inset 3px 3px 5px rgba(255, 255, 255, 0.3),
    inset -4px -5px 6px rgba(80, 0, 0, 0.27),
    0 3px 4px rgba(33, 25, 24, 0.38);
  font-size: clamp(6px, 1.1vw, 10px);
  font-weight: 900;
  animation: small-apc-button-press var(--small-apc-ticket-print-cycle, 4.2s) ease-in-out forwards;
}

.small-apc-ticket-printer__push-label {
  position: absolute;
  top: 108%;
  color: #6a7378;
  font-size: clamp(5px, 0.9vw, 8px);
  font-weight: 900;
  letter-spacing: 0.13em;
}

.small-apc-ticket-printer__vent {
  position: absolute;
  left: 9%;
  bottom: 7%;
  width: 16%;
  height: 12%;
  z-index: 4;
  border-radius: 4px;
  opacity: 0.62;
  background: repeating-linear-gradient(180deg, #6d787f 0 2px, transparent 2px 5px);
}

.small-apc-ticket-printer__screw {
  position: absolute;
  z-index: 4;
  width: 2.2%;
  aspect-ratio: 1;
  border-radius: 50%;
  background: radial-gradient(circle at 34% 30%, #f8f8f8, #6d777d 75%);
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.35);
}

.small-apc-ticket-printer__screw::after {
  content: "";
  position: absolute;
  left: 18%;
  top: 45%;
  width: 64%;
  height: 10%;
  background: rgba(50, 57, 62, 0.65);
  transform: rotate(-20deg);
}

.small-apc-ticket-printer__screw--1 { left: 5%; top: 5%; }
.small-apc-ticket-printer__screw--2 { right: 5%; top: 5%; }
.small-apc-ticket-printer__screw--3 { left: 5%; bottom: 5%; }
.small-apc-ticket-printer__screw--4 { right: 5%; bottom: 5%; }

@keyframes small-apc-ticket-output {
  0%, 9% {
    opacity: 0;
    transform: translate(-50%, -99%) rotate(0deg);
  }
  10% {
    opacity: 1;
    transform: translate(-50%, -99%) rotate(0deg);
  }
  20% { transform: translate(-50%, -78%) rotate(-0.3deg); }
  24% { transform: translate(-50%, -81%) rotate(0.2deg); }
  36% { transform: translate(-50%, -55%) rotate(-0.2deg); }
  40% { transform: translate(-50%, -58%) rotate(0.15deg); }
  52% { transform: translate(-50%, -29%) rotate(-0.1deg); }
  56% { transform: translate(-50%, -32%) rotate(0.1deg); }
  68%, 94% {
    opacity: 1;
    transform: translate(-50%, 4%) rotate(0deg);
  }
  100% {
    opacity: 0;
    transform: translate(-50%, 4%) rotate(0deg);
  }
}

@keyframes small-apc-ticket-paper-flex {
  0%, 10% {
    transform: perspective(500px) rotateX(-15deg) skewX(-0.7deg);
  }
  25% {
    transform: perspective(500px) rotateX(4deg) skewX(0.4deg);
  }
  42% {
    transform: perspective(500px) rotateX(-3deg) skewX(-0.2deg);
  }
  58% {
    transform: perspective(500px) rotateX(2deg) skewX(0.1deg);
  }
  68%, 100% {
    transform: perspective(500px) rotateX(0deg) rotateY(0deg) skewX(0deg);
  }
}

@keyframes small-apc-button-press {
  0%, 3%, 12%, 100% {
    transform: translateY(0) scale(1);
    filter: brightness(1);
  }
  6% {
    transform: translateY(3px) scale(0.91);
    filter: brightness(0.82);
    box-shadow: inset 4px 5px 7px rgba(85, 0, 0, 0.4), 0 1px 2px rgba(33, 25, 24, 0.2);
  }
}

@keyframes small-apc-ticket-roller {
  0%, 9% {
    background-position-x: 0;
  }
  68% {
    background-position-x: 100px;
  }
  69%, 100% {
    background-position-x: 100px;
  }
}

@keyframes small-apc-led-pulse {
  0%, 8%, 70%, 100% {
    filter: brightness(1);
  }
  14%, 26%, 38%, 50%, 62% {
    filter: brightness(1.8);
  }
  20%, 32%, 44%, 56% {
    filter: brightness(0.75);
  }
}

@keyframes small-apc-ticket-paper-glint {
  0%, 20% {
    transform: translateX(0) rotate(10deg);
  }
  68%, 100% {
    transform: translateX(310%) rotate(10deg);
  }
}

