}

.town-marker-parking-panel-switcher--enter-backward {
  animation: townMarkerParkingPanelEnterBackward 220ms cubic-bezier(0.22, 1, 0.36, 1) both;
}

@keyframes townMarkerParkingPanelEnterForward {
  0% {
