.housing-interior-power-toggle {
  position: relative;
  z-index: 1;
  margin-top: 7px;
  display: inline-grid;
  grid-template-columns: repeat(2, minmax(44px, 1fr));
  align-items: center;
  border: 1px solid rgba(72, 100, 83, 0.2);
  border-radius: 999px;
  background: rgba(233, 239, 232, 0.82);
  padding: 2px;
  color: inherit;
  font: inherit;
  cursor: pointer;
  box-shadow:
    inset 0 1px 2px rgba(43, 61, 45, 0.12),
    0 1px 0 rgba(255, 255, 255, 0.66);
  overflow: hidden;
  transition:
    border-color 220ms ease,
    background 220ms ease,
    box-shadow 220ms ease,
    transform 160ms ease;
}

.housing-interior-power-toggle::before {
  content: '';
  position: absolute;
  top: 2px;
  left: 2px;
  width: calc(50% - 2px);
  height: calc(100% - 4px);
  border-radius: 999px;
  background:
    radial-gradient(circle at 24% 20%, rgba(255, 255, 255, 0.96), transparent 38%),
    linear-gradient(180deg, rgba(255, 255, 255, 0.98), rgba(236, 245, 241, 0.94));
  box-shadow:
    0 5px 12px rgba(28, 67, 43, 0.18),
    inset 0 1px 0 rgba(255, 255, 255, 0.94),
    inset 0 -1px 0 rgba(56, 92, 68, 0.1);
  transform: translateX(0);
  transition:
    transform 340ms cubic-bezier(0.2, 0.9, 0.2, 1.12),
    background 220ms ease,
    box-shadow 220ms ease;
  pointer-events: none;
}

.housing-interior-power-toggle::after {
  content: '';
  position: absolute;
  inset: 2px;
  border-radius: 999px;
  background: linear-gradient(90deg, rgba(85, 170, 220, 0.22), transparent 42%, rgba(206, 87, 72, 0.18));
  opacity: 0;
  transform: scaleX(0.72);
  transition: opacity 220ms ease, transform 260ms ease;
  pointer-events: none;
}

.housing-interior-power-toggle:active {
  transform: translateY(1px) scale(0.98);
}

.housing-interior-power-toggle:hover:not(:disabled) {
  border-color: rgba(53, 122, 90, 0.34);
  box-shadow:
    inset 0 1px 2px rgba(43, 61, 45, 0.12),
    0 4px 12px rgba(38, 82, 52, 0.12);
}

.housing-interior-power-panel.is-off .housing-interior-power-toggle::before {
  transform: translateX(calc(100% + 2px));
  background:
    radial-gradient(circle at 24% 20%, rgba(255, 255, 255, 0.95), transparent 38%),
    linear-gradient(180deg, rgba(255, 250, 247, 0.98), rgba(248, 229, 224, 0.94));
  box-shadow:
    0 5px 12px rgba(114, 54, 42, 0.16),
    inset 0 1px 0 rgba(255, 255, 255, 0.94),
    inset 0 -1px 0 rgba(130, 65, 52, 0.1);
}

