@keyframes housingPrepCardExpandInline {
  from {
    clip-path: inset(0 46% 0 0 round 14px);
  }
  to {
    clip-path: inset(0 0 0 0 round 14px);
  }
}

@keyframes housingPrepCardCollapseInline {
  from {
    opacity: 1;
    clip-path: inset(0 0 0 0 round 14px);
  }
  to {
    opacity: 0.82;
    clip-path: inset(0 46% 0 0 round 14px);
  }
}

@keyframes housingPrepCardDeselect {
  from {
    opacity: 1;
    transform: scale(1);
    box-shadow:
      0 0 0 2px rgba(126, 255, 190, 0.28),
      0 14px 24px rgba(38, 84, 59, 0.14),
      inset 0 0 0 1px rgba(255, 255, 255, 0.84);
  }
  to {
    opacity: 0.78;
    transform: scale(0.97);
    box-shadow:
      0 0 0 0 rgba(126, 255, 190, 0),
      0 6px 14px rgba(38, 84, 59, 0.08),
      inset 0 0 0 1px rgba(255, 255, 255, 0.7);
  }
}

@keyframes housingPrepWaterOptionsSlideIn {
  from {
    opacity: 0;
    transform: translateX(-12px);
  }
  to {
    opacity: 1;
    transform: translateX(0);
  }
}

@keyframes housingPrepWaterOptionsSlideOut {
  from {
    opacity: 1;
    transform: translateX(0);
  }
  to {
    opacity: 0;
    transform: translateX(-12px);
  }
}

@keyframes housingPrepSelectedNeon {
  0%,
  100% {
    box-shadow:
      0 0 0 2px rgba(126, 255, 190, 0.34),
      0 0 16px rgba(47, 226, 144, 0.3),
      0 16px 28px rgba(38, 84, 59, 0.14),
      inset 0 0 0 1px rgba(255, 255, 255, 0.86);
  }
  50% {
    box-shadow:
      0 0 0 3px rgba(126, 255, 190, 0.58),
      0 0 24px rgba(47, 226, 144, 0.48),
      0 18px 30px rgba(38, 84, 59, 0.16),
      inset 0 0 0 1px rgba(255, 255, 255, 0.92);
  }
}

