@keyframes housing-fridge-content-settle {
  0% {
    opacity: 0;
    transform: translateY(8px) scale(0.992);
  }
  100% {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

@keyframes housing-fridge-item-move-to-fridge {
  0% {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
  72% {
    opacity: 0.82;
    transform: translateY(-8px) scale(0.985);
  }
  100% {
    opacity: 0;
    transform: translateY(-14px) scale(0.965);
  }
}

@keyframes housing-fridge-item-move-to-freezer {
  0% {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
  72% {
    opacity: 0.82;
    transform: translateY(8px) scale(0.985);
  }
  100% {
    opacity: 0;
    transform: translateY(14px) scale(0.965);
  }
}

@media (prefers-reduced-motion: reduce) {
  .smooth-height-panel {
    transition: none;
  }

  .housing-interior-placeholder-grid--fridge .housing-interior-placeholder-card,
  .housing-interior-placeholder-grid--fridge .housing-interior-placeholder-source,
  .housing-interior-placeholder-grid--fridge .housing-interior-placeholder-item {
    animation: none;
  }

  .housing-interior-placeholder-item {
    transition: none;
  }

  .housing-interior-appliance-slot-card,
  .housing-interior-appliance-slot-card__installed,
  .housing-interior-appliance-slot-card__empty {
    transition: none;
  }

  .housing-interior-appliance-slot-card[role="button"]:hover,
  .housing-interior-appliance-slot-card[role="button"]:active,
  .housing-interior-appliance-slot-card[role="button"]:hover .housing-interior-appliance-slot-card__installed,
  .housing-interior-appliance-slot-card[role="button"]:hover .housing-interior-appliance-slot-card__empty {
    transform: none;
  }
}

