.housing-interior-day-advance-control {
  display: grid;
  grid-template-columns: minmax(80px, 120px) 1fr auto;
  gap: 10px;
  align-items: center;
}

.housing-interior-day-advance-control input {
  width: 100%;
  min-height: 42px;
  border-radius: 14px;
  border: 1px solid rgba(71, 109, 86, 0.2);
  background: rgba(255, 255, 255, 0.72);
  color: #214c35;
  font: inherit;
  font-weight: 900;
  text-align: center;
  outline: none;
}

.housing-interior-day-advance-control input:focus {
  border-color: rgba(47, 127, 88, 0.48);
  box-shadow: 0 0 0 3px rgba(47, 127, 88, 0.12);
}

.housing-interior-day-advance-control span {
  color: rgba(33, 76, 53, 0.62);
  font-size: 0.86rem;
  font-weight: 800;
}

.housing-interior-day-advance-control .button {
  min-height: 42px;
  border-radius: 14px;
  font-size: 0.92rem;
}

.housing-pc-desktop {
  margin-top: 8px;
  padding-bottom: 0;
}

.housing-pc-desktop__screen {
  overflow: hidden;
  display: grid;
  grid-template-rows: minmax(0, 1fr) auto;
  height: clamp(348px, 62vh, 520px);
  border: 1px solid rgba(17, 48, 36, 0.22);
  border-radius: 12px;
  background: #1f3e34;
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.74),
    0 16px 34px rgba(33, 59, 42, 0.12);
}

.housing-pc-desktop__wallpaper {
  position: relative;
  height: auto;
  min-height: 0;
  padding: 14px;
  background:
    linear-gradient(90deg, rgba(17, 43, 35, 0.48), rgba(17, 43, 35, 0.16) 48%, rgba(17, 43, 35, 0.06)),
    linear-gradient(0deg, rgba(15, 38, 31, 0.22), rgba(15, 38, 31, 0.08)),
    url('./assets/images/하우징/pc-desktop-wallpaper.png'),
    #244d43;
  background-position: center;
  background-size: cover;
}

.housing-pc-desktop__apps {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(68px, 76px));
  grid-auto-rows: 66px;
  grid-auto-flow: column;
  grid-template-rows: repeat(5, 66px);
  align-content: start;
  justify-content: start;
  gap: 6px 10px;
  width: 100%;
  height: calc(100% - 8px);
  max-width: 100%;
  overflow: visible;
  padding-right: 0;
}

.housing-pc-desktop.has-open-window .housing-pc-desktop__apps {
  max-width: calc(100% - 456px);
}

.housing-pc-app {
  min-height: 0;
  padding: 4px;
  border: 1px solid transparent;
  border-radius: 4px;
  background: transparent;
  color: #f8fff9;
  display: grid;
  justify-items: center;
  align-content: start;
  gap: 4px;
  text-align: center;
  cursor: pointer;
  text-shadow: 0 1px 2px rgba(0, 0, 0, 0.45);
  box-shadow: none;
  transition:
    transform 120ms ease,
    background 120ms ease,
    border-color 120ms ease;
}

.housing-pc-app:hover,
.housing-pc-app:focus-visible,
.housing-pc-app.is-selected {
  transform: translateY(-1px);
  border-color: rgba(216, 239, 223, 0.32);
  background: rgba(225, 246, 232, 0.16);
  outline: none;
}

.housing-pc-app:active {
  transform: translateY(0) scale(0.97);
}

.housing-pc-app.is-selected .housing-pc-app__label {
  padding: 1px 3px;
  border-radius: 3px;
  background: rgba(46, 110, 181, 0.95);
}

.housing-pc-app__icon {
  display: grid;
  place-items: center;
  width: 30px;
  height: 30px;
  border-radius: 8px;
  background: rgba(246, 252, 245, 0.92);
  font-size: 1.08rem;
  text-shadow: none;
  box-shadow: 0 3px 8px rgba(15, 39, 29, 0.22);
}

.housing-pc-app__label {
  max-width: 68px;
  color: #fffef5;
  font-size: 0.68rem;
  font-weight: 800;
  line-height: 1.16;
  overflow-wrap: anywhere;
}

.housing-pc-app.is-primary .housing-pc-app__icon {
  background: rgba(228, 248, 236, 0.96);
}

.housing-pc-window {
  position: absolute;
  right: 18px;
  top: 22px;
  width: min(420px, calc(100% - 118px));
  height: calc(100% - 54px);
  min-height: 118px;
  overflow: hidden;
  border: 1px solid rgba(13, 51, 34, 0.28);
  border-radius: 8px;
  background: rgba(249, 252, 244, 0.94);
  box-shadow: 0 18px 34px rgba(12, 35, 27, 0.24);
  display: grid;
  grid-template-rows: auto minmax(0, 1fr);
}

.housing-pc-window.is-active-app {
  left: 184px;
  right: auto;
  top: 16px;
  animation: housing-pc-window-open 140ms ease-out both;
}

.housing-pc-window.is-focused {
  border-color: rgba(37, 105, 67, 0.42);
  box-shadow:
    0 20px 42px rgba(12, 35, 27, 0.32),
    0 0 0 1px rgba(226, 246, 229, 0.7);
}

.housing-pc-window.is-maximized {
  left: 172px;
  right: 10px;
  top: 8px;
  width: auto !important;
  height: calc(100% - 16px);
  border-radius: 6px;
  transform: none !important;
}

.housing-pc-window__titlebar {
  min-height: 30px;
  padding: 6px 10px;
  background: rgba(230, 239, 226, 0.96);
  border-bottom: 1px solid rgba(30, 73, 49, 0.12);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  color: var(--green-strong);
  font-size: 0.82rem;
  font-weight: 900;
  cursor: grab;
  user-select: none;
  touch-action: none;
}

.housing-pc-window__titlebar:active {
  cursor: grabbing;
}

.housing-pc-window__titlebar span {
  display: flex;
  align-items: center;
  gap: 6px;
  min-width: 0;
}

.housing-pc-window__titlebar span em {
  font-style: normal;
}

.housing-pc-window__controls {
  display: flex;
  align-items: center;
  gap: 4px;
  cursor: default;
}

.housing-pc-window__controls button {
  width: 22px;
  height: 20px;
  padding: 0;
  border: 1px solid rgba(46, 85, 62, 0.12);
  border-radius: 4px;
  background: rgba(255, 255, 250, 0.5);
  color: rgba(35, 75, 52, 0.72);
  font-size: 0.78rem;
  font-weight: 900;
  line-height: 1;
  cursor: pointer;
}

.housing-pc-window__controls button:hover {
  background: rgba(221, 239, 224, 0.86);
}

.housing-pc-window__controls button:last-child:hover {
  background: rgba(196, 77, 62, 0.88);
  color: #fff;
}

.housing-pc-window__body {
  min-height: 88px;
  padding: 14px;
  display: grid;
  align-content: center;
  gap: 6px;
  color: rgba(32, 72, 50, 0.72);
  overflow: hidden;
}

.housing-pc-window__body.is-app-open {
  align-content: stretch;
  overflow: auto;
}

.housing-pc-window__resize-handle {
  position: absolute;
  z-index: 2;
  background: transparent;
}

.housing-pc-window__resize-handle--right {
  top: 30px;
  right: 0;
  bottom: 8px;
  width: 8px;
  cursor: ew-resize;
  touch-action: none;
}

.housing-pc-window__resize-handle--bottom {
  left: 8px;
  right: 8px;
  bottom: 0;
  height: 8px;
  cursor: ns-resize;
  touch-action: none;
}

.housing-pc-window__resize-handle--corner {
  right: 0;
  bottom: 0;
  width: 16px;
  height: 16px;
  cursor: nwse-resize;
  touch-action: none;
}

.housing-pc-window__resize-handle--corner::after {
  content: "";
  position: absolute;
  right: 4px;
  bottom: 4px;
  width: 7px;
  height: 7px;
  border-right: 2px solid rgba(46, 85, 62, 0.28);
  border-bottom: 2px solid rgba(46, 85, 62, 0.28);
  border-radius: 1px;
}

.housing-pc-context-menu {
  position: absolute;
  z-index: 80;
  width: 148px;
  padding: 5px;
  border: 1px solid rgba(18, 57, 41, 0.26);
  border-radius: 6px;
  background: rgba(247, 250, 243, 0.98);
  box-shadow: 0 12px 28px rgba(9, 31, 22, 0.28);
  display: grid;
  gap: 2px;
}

.housing-pc-context-menu button {
  width: 100%;
  min-height: 28px;
  padding: 5px 8px;
  border: 0;
  border-radius: 4px;
  background: transparent;
  color: rgba(30, 70, 48, 0.86);
  font-size: 0.72rem;
  font-weight: 850;
  text-align: left;
  cursor: pointer;
}

.housing-pc-context-menu button:hover,
.housing-pc-context-menu button:focus-visible {
  background: rgba(220, 239, 222, 0.86);
  outline: none;
}

.housing-pc-window__body strong {
  color: var(--green-strong);
  font-size: 1.18rem;
}

.housing-pc-window__body span {
  font-size: 0.84rem;
  font-weight: 700;
}

.housing-pc-app-view {
  display: grid;
  align-content: start;
  gap: 8px;
  min-height: 0;
}

.housing-pc-app-view > .button {
  justify-self: start;
  min-height: 32px;
  border-radius: 10px;
}

.housing-pc-installed-app-card {
  display: grid;
  grid-template-columns: 42px minmax(0, 1fr);
  align-items: center;
  gap: 10px;
  padding: 12px;
  border: 1px solid rgba(46, 93, 65, 0.14);
  border-radius: 8px;
  background: rgba(255, 255, 250, 0.74);
}

.housing-pc-installed-app-card > em {
  display: grid;
  place-items: center;
  width: 42px;
  height: 42px;
  border-radius: 10px;
  background: rgba(230, 242, 230, 0.86);
  font-size: 1.4rem;
  font-style: normal;
}

.housing-pc-installed-app-card div {
  display: grid;
  gap: 3px;
  min-width: 0;
}

.housing-pc-installed-app-card div strong {
  color: rgba(31, 70, 48, 0.88);
  font-size: 0.86rem;
}

.housing-pc-installed-app-card div span {
  color: rgba(31, 70, 48, 0.62);
  font-size: 0.74rem;
  line-height: 1.3;
}

.housing-pc-log-list {
  display: grid;
  gap: 6px;
  min-height: 0;
}

.housing-pc-log-item {
  display: grid;
  gap: 2px;
  padding: 7px 8px;
  border: 1px solid rgba(46, 93, 65, 0.12);
  border-radius: 8px;
  background: rgba(255, 255, 250, 0.72);
}

.housing-pc-log-item em {
  color: rgba(34, 73, 51, 0.52);
  font-size: 0.68rem;
  font-style: normal;
  font-weight: 800;
}

.housing-pc-log-item span {
  color: rgba(31, 70, 48, 0.8);
  font-size: 0.74rem;
  line-height: 1.24;
}

.housing-pc-calendar-grid {
  display: grid;
  grid-template-columns: repeat(7, minmax(0, 1fr));
  gap: 4px;
}

.housing-pc-calendar-cell {
  position: relative;
  min-width: 0;
  min-height: 28px;
  padding: 3px;
  border: 1px solid rgba(55, 106, 74, 0.12);
  border-radius: 7px;
  background: rgba(255, 255, 250, 0.72);
  color: rgba(35, 77, 53, 0.78);
  cursor: pointer;
}

.housing-pc-calendar-cell strong {
  font-size: 0.72rem;
}

.housing-pc-calendar-cell i {
  position: absolute;
  right: 3px;
  bottom: 3px;
  min-width: 12px;
  height: 12px;
  border-radius: 999px;
  background: rgba(57, 116, 78, 0.88);
  color: #fffef5;
  font-size: 0.55rem;
  font-style: normal;
  line-height: 12px;
}

.housing-pc-calendar-cell.is-muted {
  opacity: 0.42;
}

.housing-pc-calendar-cell.is-today {
  border-color: rgba(57, 116, 78, 0.42);
  background: rgba(227, 243, 227, 0.9);
}

.housing-pc-calendar-cell.is-selected {
  background: rgba(57, 116, 78, 0.9);
  color: #fffef5;
}

.housing-pc-desktop__taskbar {
  position: relative;
  z-index: 2;
  min-height: 32px;
  padding: 4px 8px;
  background: rgba(235, 241, 232, 0.98);
  border-top: 1px solid rgba(18, 57, 41, 0.22);
  display: flex;
  align-items: center;
  gap: 8px;
  color: rgba(31, 70, 49, 0.78);
  font-size: 0.78rem;
  font-weight: 800;
}

.housing-pc-desktop__taskbar button {
  min-height: 24px;
  padding: 4px 12px;
  border: 1px solid rgba(34, 86, 59, 0.2);
  border-radius: 4px;
  background: rgba(255, 255, 250, 0.88);
  color: var(--green-strong);
  font-weight: 900;
  cursor: pointer;
}

.housing-pc-desktop__taskbar > button.is-active {
  background: rgba(219, 240, 222, 0.96);
  border-color: rgba(34, 86, 59, 0.34);
  box-shadow: inset 0 -2px 0 rgba(44, 111, 72, 0.82);
}

.housing-pc-desktop__taskbar-apps {
  display: flex;
  gap: 4px;
}

.housing-pc-desktop__taskbar-apps button {
  width: 34px;
  height: 24px;
  padding: 0;
  border-radius: 4px;
  display: grid;
  place-items: center;
  background: rgba(255, 255, 250, 0.68);
  border: 1px solid rgba(34, 86, 59, 0.1);
  cursor: pointer;
}

.housing-pc-desktop__taskbar-apps button.is-active {
  width: 54px;
  background: rgba(223, 242, 224, 0.96);
  border-color: rgba(34, 86, 59, 0.3);
  box-shadow: inset 0 -2px 0 rgba(44, 111, 72, 0.82);
}

.housing-pc-desktop__taskbar-apps button.is-focused {
  border-color: rgba(31, 95, 60, 0.46);
  box-shadow:
    inset 0 -2px 0 rgba(36, 101, 64, 0.95),
    0 0 0 1px rgba(36, 101, 64, 0.12);
}

.housing-pc-desktop__taskbar-apps button.is-minimized {
  opacity: 0.72;
  box-shadow: inset 0 -2px 0 rgba(101, 123, 110, 0.72);
}

.housing-pc-tray {
  margin-left: auto;
  display: inline-flex;
  align-items: center;
  gap: 5px;
  color: rgba(28, 60, 44, 0.76);
  font-size: 0.72rem;
}

.housing-pc-start-menu {
  position: absolute;
  left: 8px;
  bottom: calc(100% + 6px);
  width: 230px;
  max-height: min(240px, 68vh);
  overflow: auto;
  border: 1px solid rgba(22, 59, 42, 0.22);
  border-radius: 8px;
  background: rgba(247, 250, 243, 0.98);
  box-shadow: 0 18px 38px rgba(12, 35, 27, 0.26);
  padding: 8px;
  display: grid;
  gap: 8px;
  color: rgba(30, 70, 48, 0.84);
}

.housing-pc-start-menu__head {
  padding: 8px 9px;
  border-radius: 6px;
  background: linear-gradient(135deg, rgba(48, 105, 72, 0.92), rgba(32, 75, 58, 0.94));
  color: #fffef5;
  display: grid;
  gap: 2px;
}

.housing-pc-start-menu__head strong {
  font-size: 0.86rem;
  font-weight: 950;
}

.housing-pc-start-menu__head span {
  font-size: 0.68rem;
  font-weight: 800;
  opacity: 0.82;
}

.housing-pc-start-menu__apps {
  display: grid;
  gap: 3px;
}

.housing-pc-start-menu__search {
  width: 100%;
  min-height: 32px;
  padding: 6px 9px;
  border: 1px solid rgba(34, 86, 59, 0.16);
  border-radius: 6px;
  background: rgba(255, 255, 250, 0.9);
  color: rgba(30, 70, 48, 0.88);
  font: inherit;
  font-size: 0.72rem;
  font-weight: 800;
  outline: none;
}

.housing-pc-start-menu__search:focus {
  border-color: rgba(44, 111, 72, 0.42);
  box-shadow: 0 0 0 2px rgba(44, 111, 72, 0.12);
}

.housing-pc-start-menu__apps button {
  width: 100%;
  min-height: 42px;
  padding: 6px 7px;
  border: 1px solid transparent;
  border-radius: 6px;
  background: transparent;
  color: rgba(30, 70, 48, 0.86);
  display: grid;
  grid-template-columns: 28px minmax(0, 1fr);
  align-items: center;
  gap: 8px;
  text-align: left;
  cursor: pointer;
}

.housing-pc-start-menu__apps button:hover,
.housing-pc-start-menu__apps button:focus-visible {
  border-color: rgba(47, 111, 75, 0.16);
  background: rgba(226, 241, 225, 0.78);
  outline: none;
}

.housing-pc-start-menu__apps button > span {
  display: grid;
  place-items: center;
  width: 28px;
  height: 28px;
  border-radius: 6px;
  background: rgba(255, 255, 250, 0.88);
}

.housing-pc-start-menu__apps button div {
  min-width: 0;
  display: grid;
  gap: 1px;
}

.housing-pc-start-menu__apps button strong {
  font-size: 0.76rem;
  font-weight: 950;
}

.housing-pc-start-menu__apps button em {
  color: rgba(30, 70, 48, 0.54);
  font-size: 0.64rem;
  font-style: normal;
  font-weight: 750;
}

.housing-pc-start-menu__empty {
  padding: 10px 8px;
  color: rgba(30, 70, 48, 0.56);
  font-size: 0.72rem;
  font-weight: 800;
}

.housing-pc-start-menu__footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  padding-top: 7px;
  border-top: 1px solid rgba(34, 86, 59, 0.12);
}

.housing-pc-start-menu__footer span {
  color: rgba(30, 70, 48, 0.56);
  font-size: 0.68rem;
  font-weight: 850;
}

.housing-pc-start-menu__footer button {
  min-height: 28px;
  padding: 4px 9px;
  border: 1px solid rgba(34, 86, 59, 0.16);
  border-radius: 6px;
  background: rgba(255, 255, 250, 0.8);
  color: rgba(30, 70, 48, 0.78);
  font-size: 0.7rem;
  font-weight: 900;
  cursor: pointer;
}

@keyframes housing-pc-window-open {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

.housing-pc-desktop__taskbar time {
  margin-left: 0;
  color: rgba(28, 60, 44, 0.78);
  font-size: 0.74rem;
}

.housing-interior-calendar {
  display: grid;
  gap: 12px;
  margin-top: 14px;
}

.housing-interior-calendar__head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 12px 14px;
  border: 1px solid rgba(50, 118, 82, 0.12);
  border-radius: 18px;
  background:
    linear-gradient(135deg, rgba(255, 253, 246, 0.84), rgba(237, 247, 232, 0.68)),
    rgba(255, 255, 250, 0.5);
}

.housing-interior-calendar__head div {
  display: grid;
  gap: 3px;
}

.housing-interior-calendar__head span,
.housing-interior-calendar__head em {
  color: rgba(33, 76, 53, 0.68);
  font-size: 0.84rem;
  font-style: normal;
  font-weight: 850;
}

.housing-interior-calendar__head strong {
  color: #1d5c3b;
  font-size: 1.14rem;
  font-weight: 950;
}

.housing-interior-calendar__weekdays,
.housing-interior-calendar__grid {
  display: grid;
  grid-template-columns: repeat(7, minmax(0, 1fr));
  gap: 7px;
}

.housing-interior-calendar__weekdays span {
  color: rgba(33, 76, 53, 0.66);
  font-size: 0.78rem;
  font-weight: 950;
  text-align: center;
}

.housing-interior-calendar__cell {
  min-height: 68px;
  display: grid;
  align-content: start;
  gap: 7px;
  padding: 9px;
  border: 1px solid rgba(50, 118, 82, 0.12);
  border-radius: 14px;
  background: rgba(255, 255, 250, 0.62);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.58);
  color: inherit;
  text-align: left;
}

.housing-interior-calendar__cell.is-muted {
  opacity: 0.42;
}

.housing-interior-calendar__cell.is-today {
  border-color: rgba(47, 125, 82, 0.42);
  background: rgba(223, 246, 229, 0.72);
}

.housing-interior-calendar__cell.is-selected {
  border-color: rgba(218, 159, 58, 0.7);
  box-shadow:
    0 0 0 2px rgba(237, 187, 80, 0.22),
    inset 0 1px 0 rgba(255, 255, 255, 0.62);
}

.housing-interior-calendar__cell strong {
  color: #214c35;
  font-size: 0.92rem;
  font-weight: 950;
}

.housing-interior-calendar__events {
  display: flex;
  min-width: 0;
  flex-wrap: nowrap;
  align-items: center;
  gap: 4px;
}

.housing-interior-calendar__events span {
  padding: 3px 6px;
  border-radius: 999px;
  background: rgba(50, 118, 82, 0.1);
  color: #28543c;
  font-size: 0.72rem;
  font-weight: 950;
  line-height: 1;
}

.housing-interior-calendar__events em {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: rgba(33, 76, 53, 0.74);
  font-size: 0.72rem;
  font-style: normal;
  font-weight: 850;
}

.housing-interior-calendar__editor {
  display: grid;
  grid-template-columns: 1.1fr 1fr 1fr auto;
  gap: 10px;
  align-items: end;
  padding: 12px;
  border: 1px solid rgba(50, 118, 82, 0.12);
  border-radius: 18px;
  background:
    linear-gradient(135deg, rgba(255, 253, 246, 0.76), rgba(237, 247, 232, 0.58)),
    rgba(255, 255, 250, 0.42);
}

.housing-interior-calendar__selected,
.housing-interior-calendar__editor label {
  display: grid;
  gap: 5px;
}

.housing-interior-calendar__selected span,
.housing-interior-calendar__selected em,
.housing-interior-calendar__editor label span {
