  flex: 0 0 auto;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 6px;
}

.warehouse-storage-transport-dock-preview {
  position: absolute;
  left: 14px;
  z-index: 2;
  width: 156px;
  display: block;
  overflow: hidden;
  border-radius: 18px;
  pointer-events: none;
}

.warehouse-storage-transport-dock-preview.is-pending-target {
  overflow: visible;
}

.warehouse-storage-transport-dock-preview.is-box-load-preview {
  width: 136px;
}

.warehouse-storage-transport-dock-preview.is-empty {
  pointer-events: auto;
}

.warehouse-storage-transport-dock-preview.has-empty-pallet-action {
  pointer-events: auto;
}

.warehouse-storage-transport-dock-preview.can-pick-boxes {
  pointer-events: auto;
}

.warehouse-storage-transport-dock-preview.can-confirm-box-load {
  pointer-events: auto;
}

.warehouse-storage-transport-dock-preview.is-machine-dock {
  top: 46px;
}

.warehouse-storage-transport-dock-preview.is-tool-dock {
  bottom: 82px;
}

.warehouse-harvest-slot-card--transport-dock-preview {
  transform-origin: center center;
}

.warehouse-storage-transport-dock-preview__slot-shell-motion-layer {
  position: absolute;
  inset: 0;
  z-index: 3;
  pointer-events: none;
  overflow: hidden;
  border-radius: inherit;
}

.warehouse-storage-transport-dock-preview__slot-shell-motion {
  position: absolute;
  inset: 0;
  pointer-events: none;
}

.warehouse-storage-transport-dock-preview__slot-shell-motion--undock {
  animation: warehouse-harvest-slot-shell-undock 800ms cubic-bezier(0.34, 0.02, 0.24, 1) both;
}

.warehouse-harvest-slot-card--transport-dock-slot-shell-docking {
  animation: warehouse-harvest-slot-shell-grid-dock 800ms cubic-bezier(0.22, 0.88, 0.24, 1);
  transform-origin: center 78%;
}

.warehouse-harvest-slot-card--transport-dock-preview.warehouse-harvest-slot-card--actionable {
  cursor: pointer;
}

.warehouse-harvest-slot-card--transport-dock-pending-target {
  border-style: solid;
  border-color: color-mix(in srgb, var(--warehouse-slot-accent) 88%, #1c6447 12%);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.82),
    0 0 0 3px color-mix(in srgb, var(--warehouse-slot-accent) 20%, transparent),
    0 12px 22px rgba(22, 78, 52, 0.14);
}

.warehouse-harvest-slot-card--transport-dock-pending-target .warehouse-harvest-slot-layer-card {
  border-color: rgba(45, 96, 73, 0.28);
  background:
    linear-gradient(180deg, rgba(202, 238, 198, 0.99), rgba(164, 214, 173, 0.97)),
    repeating-linear-gradient(
      0deg,
      rgba(47, 122, 72, 0.14) 0 1px,
      transparent 1px 28px
    ),
    repeating-linear-gradient(
      90deg,
      rgba(47, 122, 72, 0.14) 0 1px,
      transparent 1px 28px
    );
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.72),
    0 10px 18px rgba(28, 74, 56, 0.1);
}

.warehouse-harvest-slot-card--transport-dock-pending-target.warehouse-harvest-slot-card--with-pallet-bg::before {
  opacity: 0.44;
}

.warehouse-storage-transport-dock-preview__base {
  position: relative;
  z-index: 1;
}

.warehouse-storage-transport-dock-preview__base.is-covered {
  opacity: 0;
}

.warehouse-storage-transport-dock-preview__overlay {
  position: absolute;
  inset: 0;
  z-index: 2;
  pointer-events: none;
}

.warehouse-storage-transport-dock-preview__overlay .warehouse-harvest-slot-card--transport-dock-preview {
  pointer-events: auto;
}

.warehouse-storage-transport-dock-preview__overlay.is-pre-docking .warehouse-harvest-slot-card--transport-dock-preview {
  opacity: 1;
  transform: translate3d(0, 26px, 0) scale(0.985);
  filter: saturate(0.98) blur(0.18px);
}

.warehouse-harvest-slot-card--transport-box-preview {
  min-height: 104px;
  height: 104px;
  padding: 12px;
  background:
    linear-gradient(180deg, rgba(232, 247, 236, 0.96), rgba(214, 238, 223, 0.94));
}

.warehouse-storage-transport-box-preview {
  display: grid;
  gap: 10px;
}

.warehouse-storage-transport-box-preview__grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 5px;
}

.warehouse-storage-transport-box-preview__box {
  width: 17px;
  height: 17px;
  border-radius: 5px;
}

.warehouse-storage-transport-box-preview__box-button {
  padding: 0;
  border: 0;
  background: transparent;
  appearance: none;
  -webkit-appearance: none;
  cursor: pointer;
}

.warehouse-storage-transport-box-preview__meta {
  display: grid;
  gap: 2px;
}

.warehouse-storage-transport-box-preview__meta strong {
  font-size: 0.95rem;
  line-height: 1;
  color: #214e3d;
}

.warehouse-storage-transport-box-preview__meta span {
  font-size: 0.73rem;
  color: rgba(33, 78, 61, 0.74);
}

.warehouse-storage-transport-box-preview--empty .warehouse-storage-transport-box-preview__box {
  opacity: 0.32;
}

.warehouse-storage-transport-selected__slot-block {
  display: grid;
  gap: 6px;
  margin-top: 8px;
}

.warehouse-storage-transport-selected__slot-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
}

.warehouse-storage-transport-selected__slot-head strong {
  font-size: 0.88rem;
  color: #285141;
}

.warehouse-storage-transport-selected__slot-head span,
.warehouse-storage-transport-selected__slot-status {
  font-size: 0.76rem;
  color: rgba(47, 77, 61, 0.7);
}

.warehouse-storage-transport-dock-preview.is-empty .warehouse-storage-transport-dock-preview__base > .warehouse-harvest-slot-card--transport-dock-preview {
  border-style: dashed;
  background:
    linear-gradient(180deg, rgba(250, 252, 247, 0.92), rgba(236, 244, 236, 0.88));
  box-shadow:
    inset 0 0 0 1px rgba(255, 255, 255, 0.55),
    0 10px 18px rgba(36, 74, 56, 0.08);
}

.warehouse-storage-transport-dock-preview__action-button {
  width: 100%;
  margin-top: auto;
  position: relative;
  z-index: 6;
  pointer-events: auto;
}

.warehouse-storage-transport-dock-preview.has-empty-pallet-action .warehouse-harvest-slot-card--transport-dock-preview {
  position: relative;
  pointer-events: auto;
}

.warehouse-storage-transport-dock-preview__ghost {
  pointer-events: none;
  z-index: 3;
}

.warehouse-storage-transport-dock-preview.is-pending-docking .warehouse-harvest-slot-card--transport-dock-preview.is-hidden-before-docking {
  opacity: 0;
  pointer-events: none;
}

.warehouse-storage-transport-dock-preview__ghost.is-undocking::after {
  content: '';
  position: absolute;
  inset: -4px -3px -5px -3px;
  border-radius: 22px;
  pointer-events: none;
}

.warehouse-storage-transport-dock-preview__ghost.is-undocking .warehouse-harvest-slot-card--transport-dock-preview {
  animation: warehouse-transport-dock-release-out 620ms cubic-bezier(0.22, 0.72, 0.2, 1) both;
}

.warehouse-storage-transport-dock-preview__ghost.is-undocking::after {
  animation: warehouse-transport-dock-clamp-out 620ms cubic-bezier(0.22, 0.72, 0.2, 1) both;
}

.warehouse-storage-transport-selected__image {
  flex: 1 1 auto;
  min-height: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 2px 0 0 134px;
}

.warehouse-storage-transport-selected__image img {
  max-width: 100%;
  max-height: 176px;
  width: auto;
  height: auto;
  object-fit: contain;
  filter: none;
}

.warehouse-storage-transport-dock-preview.is-tool-dock + .warehouse-storage-transport-selected__image {
  padding-left: 122px;
  padding-bottom: 26px;
}

.warehouse-harvest-slot-card--moving-source {
  border-style: dashed;
  border-color: rgba(78, 116, 96, 0.34);
  background:
    linear-gradient(180deg, rgba(235, 247, 238, 0.94), rgba(227, 241, 232, 0.9));
  box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.72);
}

.warehouse-harvest-slot-card--moving-source::after {
  content: '';
  position: absolute;
  inset: 18px;
  border-radius: 18px;
  border: 1px dashed rgba(62, 108, 84, 0.22);
  pointer-events: none;
}

.warehouse-harvest-slot-box.is-box-pickable {
  cursor: pointer;
  pointer-events: auto;
  transition: transform 140ms ease, filter 140ms ease, box-shadow 140ms ease;
}

.warehouse-harvest-slot-box.is-box-pickable:hover {
  transform: translateY(-1px) scale(1.05);
  filter: saturate(1.04) brightness(1.02);
  box-shadow: 0 5px 10px rgba(52, 94, 66, 0.18);
}

@keyframes warehouse-transport-dock-preview-flight {
  0% {
    opacity: 0.96;
    transform:
      translate3d(var(--dock-preview-from-x, -24px), var(--dock-preview-from-y, 34px), 0)
      scale(var(--dock-preview-from-scale-x, 1.8), var(--dock-preview-from-scale-y, 1.8));
    filter: saturate(0.96) blur(0.3px);
  }
  36% {
    opacity: 0.99;
    transform:
      translate3d(
        var(--dock-preview-from-x, -24px),
        calc(var(--dock-preview-from-y, 34px) + 52px),
        0
      )
      scale(
        calc((var(--dock-preview-from-scale-x, 1.8) * 0.62) + 0.38),
        calc((var(--dock-preview-from-scale-y, 1.8) * 0.62) + 0.38)
      );
    filter: saturate(1) blur(0.12px);
  }
  78% {
    opacity: 1;
    transform: translate3d(14px, 10px, 0) scale(1.04);
    filter: saturate(1.03) blur(0);
  }
  100% {
    opacity: 1;
    transform: translate3d(0, 0, 0) scale(1);
    filter: saturate(1) blur(0);
  }
}

@keyframes warehouse-transport-dock-preview-meta-in {
  0% {
    opacity: 0;
    transform: translate3d(0, 12px, 0);
  }
  100% {
    opacity: 1;
    transform: translate3d(0, 0, 0);
  }
}

@keyframes warehouse-transport-dock-release-out {
  0% {
    opacity: 1;
    transform: translate3d(0, 0, 0) scale(1);
    filter: saturate(1) blur(0);
  }
  18% {
    opacity: 1;
    transform: translate3d(0, 7px, 0) scale(1);
    filter: saturate(1.02) blur(0);
  }
  34% {
    opacity: 1;
    transform: translate3d(0, 12px, 0) scale(1);
    filter: saturate(0.99) blur(0.04px);
  }
  54% {
    opacity: 0.98;
    transform: translate3d(0, 10px, 0) scale(1);
    filter: saturate(0.98) blur(0.06px);
  }
  100% {
    opacity: 0;
    transform: translate3d(0, 34px, 0) scale(1);
    filter: saturate(0.9) blur(0.36px);
  }
}

@keyframes warehouse-transport-dock-clamp-out {
  0% {
    opacity: 0;
    box-shadow:
      0 0 0 0 rgba(74, 118, 92, 0),
      inset 0 0 0 0 rgba(255, 255, 255, 0);
  }
  22% {
    opacity: 1;
    box-shadow:
      0 7px 0 rgba(48, 91, 67, 0.36),
      0 0 0 2px rgba(78, 122, 96, 0.18),
      inset 0 0 0 1px rgba(255, 255, 255, 0.44);
  }
  42% {
    opacity: 0.92;
    box-shadow:
      0 10px 0 rgba(48, 91, 67, 0.24),
      0 0 0 1px rgba(78, 122, 96, 0.1),
      inset 0 0 0 1px rgba(255, 255, 255, 0.28);
  }
  100% {
    opacity: 0;
    box-shadow:
      0 18px 14px rgba(39, 78, 58, 0),
      inset 0 0 0 0 rgba(255, 255, 255, 0);
  }
}

.warehouse-storage-transport-selected__mode-block {
