      rgba(146, 96, 45, 0.22) 0 14%,
      transparent 14% 18%,
      rgba(146, 96, 45, 0.18) 18% 32%,
      transparent 32% 36%,
      rgba(146, 96, 45, 0.2) 36% 64%,
      transparent 64% 68%,
      rgba(146, 96, 45, 0.18) 68% 82%,
      transparent 82% 86%,
