@keyframes warehouse-harvest-box-fill-drop {
  0% {
    opacity: 0.18;
    transform: translateY(-24px) scale(0.93);
    filter: saturate(0.92) brightness(1.06);
    box-shadow: 0 18px 28px rgba(52, 94, 66, 0.12);
  }
  78% {
    opacity: 1;
    transform: translateY(2px) scale(1.02);
    filter: saturate(1.04) brightness(1.015);
    box-shadow: 0 8px 14px rgba(52, 94, 66, 0.16);
