    transform: translateY(-1px) scale(0.995);
    filter: saturate(1.01) brightness(1.005);
    box-shadow: 0 3px 6px rgba(52, 94, 66, 0.08);
  }
  100% {
    opacity: 1;
    transform: translateY(0) scale(1);
    filter: none;
    box-shadow: none;
  }
}

