.spray-mix-visual__bar {
  margin-top: 10px;
  position: relative;
  height: 32px;
  border-radius: 999px;
  overflow: hidden;
  background: #f6f0df;
  border: 1px solid rgba(40, 84, 63, 0.28);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.58);
}

.spray-mix-visual__bar-fill {
  position: absolute;
  left: 0;
  top: 0;
  bottom: 0;
  border-radius: 999px;
  background: linear-gradient(90deg, #7fc2ea 0%, #9dd7f5 55%, #b9e8fb 100%);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.38);
  transition: width 900ms cubic-bezier(0.22, 1, 0.36, 1);
  z-index: 1;
  overflow: hidden;
}

.spray-mix-visual__bar-fill::before {
  content: '';
  position: absolute;
  inset: 0;
  border-radius: inherit;
  background: linear-gradient(90deg, #6f9fd8 0%, #8f94e0 55%, #a58fe0 100%);
  opacity: 0;
  transition: opacity 980ms cubic-bezier(0.22, 1, 0.36, 1);
}

.spray-mix-visual__bar-fill::after {
  content: '';
  position: absolute;
  inset: 0;
  border-radius: inherit;
  background: linear-gradient(90deg, #d7ab2f 0%, #f0c84a 55%, #f7dc7a 100%);
  opacity: 0;
  transition: opacity 980ms cubic-bezier(0.22, 1, 0.36, 1);
}

