.auth-modal-notice {
  width: min(420px, calc(100vw - 28px));
  align-self: center;
  border-color: rgba(181, 124, 67, 0.28);
  background:
    radial-gradient(circle at top left, rgba(255, 233, 196, 0.56), transparent 42%),
    linear-gradient(180deg, rgba(255, 251, 242, 0.98), rgba(255, 244, 224, 0.96));
  box-shadow:
    0 20px 44px rgba(67, 46, 22, 0.16),
    0 0 0 1px rgba(198, 146, 81, 0.1),
    0 0 26px rgba(232, 186, 118, 0.18);
  animation:
    auth-modal-panel-open 260ms cubic-bezier(0.22, 1, 0.36, 1) both,
    auth-notice-float 2.6s ease-in-out infinite,
    auth-notice-glow 2.2s ease-in-out infinite;
}

