}

@keyframes auth-modal-warning-blink {
  0%, 100% {
    opacity: 1;
  }
  50% {
    opacity: 0.35;
  }
}

@keyframes auth-modal-panel-open {
  0% {
    opacity: 0;
    transform: translateY(14px);
  }
  100% {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes auth-notice-float {
  0%,
  100% {
    transform: translateY(0);
  }
  50% {
    transform: translateY(-7px);
  }
}

@keyframes auth-notice-glow {
  0%,
  100% {
    box-shadow:
      0 20px 44px rgba(67, 46, 22, 0.16),
      0 0 0 1px rgba(198, 146, 81, 0.1),
      0 0 18px rgba(232, 186, 118, 0.15);
  }
  50% {
    box-shadow:
      0 24px 50px rgba(67, 46, 22, 0.18),
      0 0 0 1px rgba(198, 146, 81, 0.14),
      0 0 34px rgba(232, 186, 118, 0.28);
  }
}

