.shop-terminal-modal--card-new .terminal-function-row span:nth-child(1) {
  background: rgba(239, 68, 68, 0.68);
}

.shop-terminal-modal--card-new .terminal-function-row span:nth-child(2) {
  background: rgba(250, 204, 21, 0.68);
}

.shop-terminal-modal--card-new .terminal-function-row span:nth-child(3) {
  background: rgba(34, 197, 94, 0.72);
  animation: shopTerminalApprovePulseNew var(--duration) ease-in-out forwards;
}

.shop-terminal-modal--card-new .contactless-mark {
  width: 58px;
  height: 50px;
  border-radius: 16px;
  display: grid;
  place-items: center;
  position: relative;
  overflow: hidden;
  background:
    radial-gradient(circle at 26% 22%, rgba(255, 255, 255, 0.12), transparent 32%),
    linear-gradient(145deg, rgba(73, 111, 91, 0.64), rgba(31, 60, 49, 0.92));
  border: 1px solid rgba(196, 230, 210, 0.2);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.12),
    inset 0 -10px 18px rgba(4, 19, 13, 0.2),
    0 8px 16px rgba(9, 25, 18, 0.18);
}

.shop-terminal-modal--card-new .contactless-mark::before {
  content: "";
  position: absolute;
  inset: 8px;
  border-radius: 12px;
  border: 1px solid rgba(219, 255, 235, 0.09);
  pointer-events: none;
}

.shop-terminal-modal--card-new .contactless-icon {
  width: 34px;
  height: 32px;
  position: relative;
  animation: shopTerminalContactPulseNew var(--duration) ease-in-out forwards;
}

.shop-terminal-modal--card-new .contactless-icon__dot {
  position: absolute;
  left: 6px;
  top: 50%;
  width: 5px;
  height: 5px;
  border-radius: 999px;
  background: rgba(203, 247, 223, 0.82);
  transform: translateY(-50%);
  box-shadow: 0 0 8px rgba(134, 239, 172, 0.32);
}

.shop-terminal-modal--card-new .contactless-icon__wave {
  position: absolute;
  top: 50%;
  left: 3px;
  border-radius: 50%;
  border-right: 3px solid rgba(203, 247, 223, 0.66);
  border-top: 3px solid transparent;
  border-bottom: 3px solid transparent;
  transform: translateY(-50%);
}

.shop-terminal-modal--card-new .contactless-icon__wave--sm {
  width: 13px;
  height: 15px;
}

.shop-terminal-modal--card-new .contactless-icon__wave--md {
  width: 21px;
  height: 24px;
  opacity: 0.82;
}

.shop-terminal-modal--card-new .contactless-icon__wave--lg {
  width: 29px;
  height: 32px;
  opacity: 0.58;
}

.shop-terminal-modal--card-new .pay-spark {
  position: absolute;
  width: 9px;
  height: 9px;
  border-radius: 50%;
  background: #f7d56b;
  box-shadow: 0 0 18px rgba(247, 213, 107, 0.65);
  opacity: 0;
  z-index: 45;
  animation: shopTerminalSparkPopNew var(--duration) ease-out forwards;
}

.shop-terminal-modal--card-new .pay-spark:nth-of-type(1) {
  left: 16%;
  top: 42%;
}

.shop-terminal-modal--card-new .pay-spark:nth-of-type(2) {
  left: 26%;
  top: 29%;
  animation-delay: 80ms;
}

.shop-terminal-modal--card-new .pay-spark:nth-of-type(3) {
  left: 48%;
  top: 38%;
  animation-delay: 160ms;
}

.shop-terminal-modal--card-new .pay-spark:nth-of-type(4) {
  left: 67%;
  top: 30%;
  animation-delay: 240ms;
}

.shop-terminal-modal--card-new .pay-spark:nth-of-type(5) {
  left: 78%;
  top: 45%;
  animation-delay: 320ms;
}

