  }
  100% {
    opacity: 1;
    transform: rotate(-9deg) scale(1.28);
  }
}

@keyframes shopTerminalCardSwipeNew {
  0% {
    opacity: 0;
    transform: translate3d(-350px, 12px, 0) rotate(0deg) scale(1);
  }

  8% {
    opacity: 1;
    transform: translate3d(-320px, 12px, 0) rotate(0deg) scale(1);
  }

  92% {
    opacity: 1;
    transform: translate3d(320px, 12px, 0) rotate(0deg) scale(1);
  }

  100% {
    opacity: 0;
    transform: translate3d(350px, 12px, 0) rotate(0deg) scale(1);
  }
}

@keyframes shopTerminalCardTrailNew {
  0%, 16% {
    opacity: 0;
    transform: translateY(-50%) scaleX(0.45);
  }

  30%, 66% {
    opacity: 1;
    transform: translateY(-50%) scaleX(1);
  }

  84%, 100% {
    opacity: 0;
    transform: translateY(-50%) scaleX(0.62);
  }
}

@keyframes shopTerminalKeypadTapNew {
  0%, 44%, 100% {
