    opacity: 0.46;
    transform: scale(0.95);
  }

  55%, 78% {
    opacity: 1;
    transform: scale(1.06);
    filter: drop-shadow(0 0 10px rgba(134, 239, 172, 0.4));
  }

  100% {
    opacity: 0.72;
    transform: scale(1);
  }
}

@keyframes shopTerminalSparkPopNew {
  0%, 20% {
    opacity: 0;
    transform: translate(0, 0) scale(0.4);
  }

  38% {
    opacity: 1;
  }

  62% {
    opacity: 0;
    transform: translate(18px, -20px) scale(1.15);
  }

  100% {
    opacity: 0;
  }
}

@media (max-width: 420px) {
  .shop-terminal-modal--card-new {
    padding: 22px 16px 18px;
    border-radius: 24px;
  }

  .shop-terminal-modal--card-new .confirm-modal__title {
    font-size: 26px;
  }

  .shop-terminal-modal--card-new .shop-terminal-stage {
    min-height: 360px;
    padding-inline: 10px;
  }

  .shop-terminal-modal--card-new .shop-terminal-device {
    width: 100%;
  }

  .shop-terminal-modal--card-new .shop-terminal-card-swipe .sim-card {
    width: min(196px, 82%);
  }

  .shop-terminal-modal--card-new .receipt {
    width: 122px;
  }
}

@media (prefers-reduced-motion: reduce) {
  .shop-terminal-modal--card-new *,
  .shop-terminal-modal--card-new *::before,
  .shop-terminal-modal--card-new *::after {
    animation-duration: 0.001ms !important;
    animation-iteration-count: 1 !important;
    scroll-behavior: auto !important;
  }

  .shop-terminal-modal--card-new .shop-terminal-screen__state--done,
  .shop-terminal-modal--card-new .receipt {
    opacity: 1;
    transform: none;
  }

  .shop-terminal-modal--card-new .shop-terminal-card-swipe {
    opacity: 0;
  }
}

.wallet-modal {
  width: min(980px, 96vw);
  max-height: min(88vh, 980px);
  overflow-y: auto;
  overflow-x: hidden;
}

.wallet-summary {
  margin-top: 12px;
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 10px;
}

.wallet-summary__item {
  border: 1px solid rgba(40, 84, 63, 0.18);
  border-radius: 12px;
  padding: 10px 12px;
  background: rgba(255, 255, 255, 0.66);
}

.wallet-summary__item span {
  display: block;
  font-size: 0.8rem;
  color: rgba(36, 69, 55, 0.72);
}

.wallet-summary__item strong {
  display: block;
  margin-top: 4px;
  color: #1f4a39;
  font-size: 1.02rem;
}

.wallet-tabs {
  margin-top: 12px;
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 8px;
}

.wallet-tab {
  min-height: 38px;
  border: 1px solid rgba(40, 84, 63, 0.16);
  border-radius: 12px;
  background: rgba(255, 255, 255, 0.58);
  color: rgba(33, 74, 57, 0.82);
  font-weight: 800;
  cursor: pointer;
}

.wallet-tab.is-active {
  border-color: rgba(47, 122, 81, 0.58);
  background: linear-gradient(180deg, rgba(236, 250, 239, 0.88), rgba(207, 237, 216, 0.82));
  color: #1d4734;
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.7),
    0 8px 18px rgba(40, 84, 63, 0.12);
}

.wallet-detail-panel {
  margin-top: 12px;
