    repeating-linear-gradient(0deg, rgba(48, 100, 70, 0.08) 0 1px, rgba(48, 100, 70, 0) 1px 9px),
    radial-gradient(circle at 23% 50%, rgba(248, 235, 188, 0.9) 0 18%, rgba(248, 235, 188, 0) 19%),
    radial-gradient(circle at 78% 50%, rgba(221, 236, 201, 0.78) 0 19%, rgba(221, 236, 201, 0) 20%),
