.cash-note::after {
  content: '';
  position: absolute;
  left: 0;
  right: 0;
  top: 50%;
  height: 32%;
  transform: translateY(-50%);
  background:
    linear-gradient(90deg, rgba(28, 74, 48, 0) 0 8%, rgba(28, 74, 48, 0.16) 8% 9%, rgba(28, 74, 48, 0) 9% 91%, rgba(28, 74, 48, 0.16) 91% 92%, rgba(28, 74, 48, 0) 92%),
