.control-toggle {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: space-between;
  width: 132px;
  height: 42px;
  padding: 0 12px;
  border-radius: 999px;
  border: 1px solid rgba(41, 58, 47, 0.25);
  background: #eef1ed;
  cursor: pointer;
  user-select: none;
  transition: background-color 120ms ease;
}

.control-toggle:disabled {
  opacity: 0.55;
  cursor: not-allowed;
}

.control-toggle__label {
  position: relative;
  z-index: 2;
  font-weight: 900;
  font-size: 18px;
  letter-spacing: 0.5px;
  line-height: 1;
  color: #a8aea7;
  transition: color 180ms ease;
}

.control-toggle.is-on .control-toggle__label--on {
  color: #2e9a3f;
}

.control-toggle.is-off .control-toggle__label--off {
  color: #d13b2f;
}

.control-toggle__thumb {
  position: absolute;
  top: 3px;
  left: 3px;
  width: 62px;
  height: 34px;
  border-radius: 999px;
  background: #ffffff;
  border: 1px solid rgba(77, 86, 80, 0.22);
  transition: transform 180ms ease;
}

.control-toggle.is-off .control-toggle__thumb {
  transform: translateX(64px);
}

.cold-control-panel {
  margin-top: 2px;
  display: grid;
  gap: 8px;
  justify-items: center;
}

.cold-control-panel__display-wrap {
  position: relative;
  width: 150px;
  padding: 8px 8px 8px;
  border-radius: 7px;
  border: 2px solid #6f7b85;
  background: linear-gradient(180deg, #c9d1d7 0%, #b4bec7 100%);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.45),
    0 6px 14px rgba(38, 47, 54, 0.12);
}

.cold-control-panel__display-wrap--with-side-keys {
  width: 154px;
  display: grid;
  grid-template-columns: minmax(0, 1fr) 30px;
  align-items: center;
  column-gap: 6px;
  padding: 6px 5px;
}

.cold-control-panel__brand,
.cold-control-panel__model {
  position: absolute;
  top: 4px;
  font-size: 9px;
  font-weight: 800;
  color: #44515b;
  letter-spacing: 0.4px;
}

.cold-control-panel__brand {
  left: 8px;
}

.cold-control-panel__model {
  right: 8px;
}

.cold-control-panel__display {
  width: 100%;
  min-height: 44px;
  border-radius: 4px;
  border: 1px solid #2b3137;
  background: linear-gradient(180deg, #182025 0%, #0a0f13 100%);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 7px 6px 6px;
  box-sizing: border-box;
}

.seven-seg-display {
  display: inline-flex;
  width: 100%;
  align-items: flex-end;
  justify-content: space-between;
  min-height: 28px;
}

.seven-seg-display__value {
  display: inline-flex;
  align-items: flex-end;
  gap: 4px;
  justify-content: flex-end;
  flex: 1;
}

.seven-seg {
  position: relative;
  display: inline-block;
  width: 18px;
  height: 30px;
  filter: drop-shadow(0 0 4px rgba(255, 64, 42, 0.28));
}

.seven-seg--minus {
  width: 13px;
}

.seven-seg--sign {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: 0 0 13px;
  margin-right: 8px;
  align-self: stretch;
}

.seven-seg--dot {
  width: 6px;
  height: 30px;
}

.seven-seg--dot::after {
  content: "";
  position: absolute;
  right: 0;
  bottom: 2px;
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: #ff442d;
  box-shadow: 0 0 7px rgba(255, 68, 45, 0.6);
}

.seven-seg__segment {
  position: absolute;
  background: rgba(115, 18, 16, 0.28);
  opacity: 0.55;
  transition: opacity 140ms ease, background 140ms ease, box-shadow 140ms ease;
}

.seven-seg__segment.is-on {
  background: linear-gradient(180deg, #ff745c 0%, #ff3f28 52%, #d81d17 100%);
  opacity: 1;
  box-shadow:
    0 0 8px rgba(255, 67, 42, 0.35),
    0 0 2px rgba(255, 118, 94, 0.65);
}

.seven-seg__segment--a,
.seven-seg__segment--d,
.seven-seg__segment--g {
  left: 4px;
  width: 10px;
  height: 3px;
  clip-path: polygon(14% 0, 86% 0, 100% 50%, 86% 100%, 14% 100%, 0 50%);
}

.seven-seg__segment--a {
  top: 0;
}

.seven-seg__segment--g {
  top: 13px;
}

.seven-seg__segment--d {
  bottom: 0;
}

.seven-seg__segment--b,
.seven-seg__segment--c,
.seven-seg__segment--e,
.seven-seg__segment--f {
  width: 3px;
  height: 11px;
  clip-path: polygon(0 14%, 50% 0, 100% 14%, 100% 86%, 50% 100%, 0 86%);
}

.seven-seg__segment--b {
  top: 2px;
  right: 0;
}

.seven-seg__segment--c {
  bottom: 2px;
  right: 0;
}

.seven-seg__segment--e {
  bottom: 2px;
  left: 0;
}

.seven-seg__segment--f {
  top: 2px;
  left: 0;
}

.cold-control-panel__keys {
  display: flex;
  gap: 8px;
}

.cold-control-panel__keys--vertical {
  flex-direction: column;
  gap: 4px;
}

.cold-control-panel__keys--embedded {
  position: static;
  transform: none;
  align-self: center;
