}

.control-action-pill {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 132px;
  height: 42px;
  padding: 0 14px;
  border-radius: 999px;
  border: 1px solid rgba(41, 58, 47, 0.25);
  background: #eef1ed;
  color: #2f5f3f;
  font-weight: 800;
  font-size: 18px;
  line-height: 1;
  letter-spacing: -0.3px;
  white-space: nowrap;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.75);
  cursor: pointer;
  user-select: none;
  transition: background-color 140ms ease, border-color 140ms ease, color 140ms ease, transform 100ms ease;
}

.control-action-pill:hover:not(:disabled) {
  background: #f5f7f4;
  border-color: rgba(41, 58, 47, 0.32);
}

.control-action-pill:active:not(:disabled) {
  transform: translateY(1px);
}

.control-action-pill:disabled {
  opacity: 0.55;
  cursor: not-allowed;
}

.control-slot-empty {
  width: 100%;
  min-height: 0;
  flex: 1;
  border: 2px dashed rgba(45, 73, 58, 0.35);
  border-radius: 16px;
  display: flex;
  align-items: center;
  justify-content: center;
  box-sizing: border-box;
  padding: 10px;
  margin: 0;
}

.parking-storage-tabs {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin: 0 0 10px;
}

.parking-storage-tab {
  border: 1px solid rgba(43, 89, 64, 0.22);
  border-radius: 10px;
  background: rgba(255, 255, 255, 0.78);
  color: #28533d;
  display: inline-flex;
  align-items: center;
  gap: 7px;
  min-height: 40px;
  padding: 8px 14px;
  box-shadow: 0 8px 18px rgba(35, 63, 45, 0.06);
  font-weight: 900;
  transition:
    transform 0.16s ease,
    border-color 0.16s ease,
    background 0.16s ease,
    box-shadow 0.16s ease;
}

.parking-storage-tab:hover {
  transform: translateY(-1px);
  border-color: rgba(46, 127, 86, 0.32);
}

.parking-storage-tab.is-active {
  background: linear-gradient(180deg, #2e7a52, #1d5b3d);
  border-color: rgba(20, 84, 52, 0.78);
  color: #f7fff9;
  box-shadow:
    0 10px 20px rgba(28, 83, 52, 0.2),
    inset 0 1px 0 rgba(255, 255, 255, 0.22);
}

.parking-storage-tab strong {
  border-radius: 7px;
  background: rgba(46, 127, 86, 0.12);
  color: #216142;
  font-size: 0.72rem;
  line-height: 1;
  padding: 5px 7px;
}

.parking-storage-tab.is-active strong {
  background: rgba(255, 255, 255, 0.18);
  color: #f7fff9;
}

.parking-storage-slot-grid {
  transform-origin: center top;
  animation: parking-storage-tab-panel-forward 260ms cubic-bezier(0.18, 0.9, 0.2, 1) both;
}

.parking-storage-slot-grid.is-back {
  animation-name: parking-storage-tab-panel-back;
}

@keyframes parking-storage-tab-panel-forward {
  0% {
    opacity: 0;
    transform: translateX(26px) translateY(4px) scale(0.992);
  }
  76% {
    opacity: 1;
    transform: translateX(-3px) translateY(0) scale(1.002);
  }
  100% {
    opacity: 1;
    transform: translateX(0) translateY(0) scale(1);
  }
}

@keyframes parking-storage-tab-panel-back {
  0% {
    opacity: 0;
    transform: translateX(-26px) translateY(4px) scale(0.992);
  }
  76% {
    opacity: 1;
    transform: translateX(3px) translateY(0) scale(1.002);
  }
  100% {
    opacity: 1;
    transform: translateX(0) translateY(0) scale(1);
  }
}

@media (prefers-reduced-motion: reduce) {
  .parking-storage-slot-grid {
    animation: none;
  }
}

