.time-transition-modal {
  position: relative;
  transform-origin: 50% 56%;
  animation: time-transition-modal-enter 560ms cubic-bezier(0.16, 1, 0.3, 1) both;
  box-shadow:
    0 30px 90px rgba(6, 14, 24, 0.38),
    0 8px 22px rgba(8, 18, 26, 0.24),
    inset 0 0 0 1px rgba(255, 255, 255, 0.08);
}

.time-transition-shell {
  transform-origin: 50% 55%;
  animation: time-transition-shell-enter 520ms cubic-bezier(0.16, 1, 0.3, 1) both;
  --confirm-modal-base-transform: translate(-50%, -50%);
}

.time-transition-backdrop {
  animation: time-transition-backdrop-enter 420ms ease-out both;
  backdrop-filter: blur(0);
}

.time-transition-modal::before {
  content: '';
  position: absolute;
  inset: -1px;
  z-index: 2;
  pointer-events: none;
  border-radius: inherit;
  background:
    radial-gradient(circle at 50% 0%, rgba(255, 244, 190, 0.24), transparent 34%),
    linear-gradient(115deg, transparent 0%, rgba(255, 255, 255, 0.2) 42%, transparent 58%);
  mix-blend-mode: screen;
  opacity: 0;
  animation: time-transition-modal-sheen 760ms cubic-bezier(0.16, 1, 0.3, 1) 70ms both;
}

.time-transition-shell.is-closing {
  animation: time-transition-shell-exit 360ms cubic-bezier(0.7, 0, 0.84, 0) both;
}

.time-transition-backdrop.is-closing {
  animation: time-transition-backdrop-exit 360ms ease-in both;
}

.time-transition-modal.is-closing {
  animation: time-transition-modal-exit 360ms cubic-bezier(0.7, 0, 0.84, 0) both;
}

.time-transition-modal__caption {
  position: absolute;
  left: 50%;
  bottom: 22px;
  transform: translateX(-50%);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 2px;
  min-width: 168px;
  padding: 10px 18px;
  border-radius: 999px;
  border: 1px solid rgba(244, 237, 219, 0.42);
  background: linear-gradient(180deg, rgba(8, 20, 30, 0.3), rgba(12, 28, 39, 0.58));
  color: rgba(255, 250, 238, 0.96);
  font-size: 0.94rem;
  font-weight: 800;
  letter-spacing: 0.08em;
  box-shadow:
    0 12px 28px rgba(6, 15, 24, 0.32),
    inset 0 1px 0 rgba(255, 255, 255, 0.12);
  backdrop-filter: blur(8px);
  pointer-events: none;
}

.time-transition-modal__caption-text {
  text-shadow: 0 1px 10px rgba(12, 19, 24, 0.38);
}

.time-transition-modal__caption-dots::after {
  content: '';
  display: inline-block;
  width: 1.6em;
  text-align: left;
  animation: time-transition-caption-dots 1.2s steps(4, end) infinite;
}

@keyframes time-transition-caption-dots {
  0%,
  24% {
    content: '';
  }
  25%,
  49% {
    content: '.';
  }
  50%,
  74% {
    content: '..';
  }
  75%,
  100% {
    content: '...';
  }
}

@keyframes time-transition-backdrop-enter {
  from {
    opacity: 0;
    backdrop-filter: blur(0);
  }
  to {
    opacity: 1;
    backdrop-filter: blur(5px);
  }
}

@keyframes time-transition-backdrop-exit {
  from {
    opacity: 1;
    backdrop-filter: blur(5px);
  }
  to {
    opacity: 0;
    backdrop-filter: blur(0);
  }
}

@keyframes time-transition-shell-enter {
  from {
    opacity: 0;
    transform: translate(-50%, -50%) translateY(22px) scale(0.94);
    filter: blur(10px) saturate(0.8);
  }
  58% {
    opacity: 1;
    transform: translate(-50%, -50%) translateY(-4px) scale(1.018);
    filter: blur(0) saturate(1.08);
  }
  to {
    opacity: 1;
    transform: translate(-50%, -50%) translateY(0) scale(1);
    filter: blur(0) saturate(1);
  }
}

@keyframes time-transition-shell-exit {
  from {
    opacity: 1;
    transform: translate(-50%, -50%) translateY(0) scale(1);
    filter: blur(0);
  }
  to {
    opacity: 0;
    transform: translate(-50%, -50%) translateY(18px) scale(0.96);
    filter: blur(8px);
  }
}

@keyframes time-transition-modal-enter {
  from {
    opacity: 0;
    transform: perspective(900px) rotateX(8deg) scale(0.96);
  }
  68% {
    opacity: 1;
    transform: perspective(900px) rotateX(-1.5deg) scale(1.01);
  }
  to {
    opacity: 1;
    transform: perspective(900px) rotateX(0) scale(1);
  }
}

@keyframes time-transition-modal-exit {
  from {
    opacity: 1;
    transform: perspective(900px) rotateX(0) scale(1);
  }
  to {
    opacity: 0;
    transform: perspective(900px) rotateX(-7deg) scale(0.97);
  }
}

@keyframes time-transition-modal-sheen {
  from {
    opacity: 0;
    transform: translateX(-34%);
  }
  42% {
    opacity: 0.75;
  }
  to {
    opacity: 0;
    transform: translateX(34%);
  }
}

