  border-radius: 12px;
  background: rgba(255, 255, 255, 0.42);
  padding: 8px;
}

.machine-refuel-can-modal__section-title {
  font-size: 0.86rem;
  font-weight: 800;
  color: rgba(28, 70, 52, 0.9);
}

.machine-parking {
  margin-top: 8px;
}

.machine-parking__label {
  font-size: 12px;
  color: rgba(45, 73, 58, 0.72);
  margin-bottom: 6px;
}

.machine-parking__grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(84px, 1fr));
  gap: 8px;
}

.machine-parking__slot {
  height: 56px;
  border: 2px dashed rgba(45, 73, 58, 0.35);
  border-radius: 12px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(255, 255, 255, 0.46);
}

.machine-parking__slot span {
  font-size: 12px;
  color: rgba(45, 73, 58, 0.38);
  font-weight: 700;
}

.control-slider-wrap {
  width: 100%;
}

.control-slider {
  width: 100%;
  appearance: none;
  height: 8px;
  border-radius: 999px;
  background: #e5e9e4;
  border: 1px solid rgba(45, 73, 58, 0.18);
  outline: none;
}

.control-slider::-webkit-slider-thumb {
  appearance: none;
  width: 18px;
  height: 18px;
  border-radius: 50%;
  border: 1px solid rgba(45, 73, 58, 0.35);
  background: #ffffff;
}

.control-slider::-moz-range-thumb {
  width: 18px;
  height: 18px;
  border-radius: 50%;
  border: 1px solid rgba(45, 73, 58, 0.35);
  background: #ffffff;
}

.control-led-board {
  border-radius: 10px;
  border: 1px solid #3f5149;
  background: #101715;
  padding: 8px 10px;
  display: grid;
  gap: 2px;
  text-align: center;
}

.control-led-board__label {
  color: rgba(206, 231, 220, 0.74);
  font-size: 11px;
  letter-spacing: 0.4px;
}

.control-led-board__value {
  color: #53ff9e;
  font-family: "Consolas", "Courier New", monospace;
  font-size: 24px;
  font-weight: 800;
  line-height: 1.05;
  letter-spacing: 0.6px;
}

.control-led-board__meta {
  color: #abdbc5;
  font-size: 11px;
}

.gas-station-board {
  border: 1px solid rgba(45, 73, 58, 0.18);
  border-radius: 16px;
  background: linear-gradient(180deg, #f6f7f2 0%, #ecefe6 100%);
  padding: 12px;
  display: grid;
  grid-template-columns: 120px minmax(0, 1fr);
  gap: 12px;
  width: min(100%, 700px);
  margin: 0 auto;
}

.fuel-tab-layout {
  display: grid;
  grid-template-columns: 280px minmax(620px, 900px);
  gap: 14px;
  align-items: stretch;
  justify-content: start;
  width: max-content;
  max-width: 100%;
  margin: 0;
  height: 100%;
  min-height: 0;
}

.fuel-tab-layout__left,
.fuel-tab-layout__right {
  min-width: 0;
  height: 100%;
  min-height: 0;
}

.fuel-tab-layout__left {
  display: flex;
  justify-content: flex-start;
  align-items: stretch;
}

.fuel-tab-layout__right {
  display: flex;
  justify-content: flex-start;
  align-items: stretch;
}

.gas-station-board--side {
  width: min(100%, 292px);
  height: 100%;
  min-height: 100%;
  margin: 0 auto;
  grid-template-columns: 1fr;
}

.gas-station-board--side .gas-station-board__pump {
  display: none;
}

.gas-station-board__pump {
  border-radius: 12px;
  background: linear-gradient(180deg, #2f4f44 0%, #243d35 100%);
  padding: 10px 8px;
  display: grid;
  grid-template-rows: 8px 1fr;
  gap: 8px;
  position: relative;
}

.gas-station-board__pump-head {
  width: 38px;
  height: 8px;
  border-radius: 999px;
  background: #a9c5b9;
  margin: 0 auto;
}

.gas-station-board__pump-body {
  border-radius: 10px;
  background: #eff5f1;
  border: 1px solid rgba(30, 56, 47, 0.2);
  padding: 8px 6px;
}

.gas-station-board__pump-screen {
  border-radius: 8px;
  text-align: center;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.8px;
  color: #0a4a31;
  background: #b9ebd2;
  border: 1px solid rgba(10, 74, 49, 0.22);
  padding: 4px 0;
}

.gas-station-board__pump-btns {
  margin-top: 8px;
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 5px;
}

.gas-station-board__pump-btns span {
  height: 7px;
  border-radius: 999px;
  background: rgba(48, 77, 66, 0.22);
}

.gas-station-board__pump-hose {
  position: absolute;
  right: -8px;
  top: 28px;
  width: 18px;
  height: 44px;
  border-right: 3px solid rgba(28, 46, 39, 0.6);
  border-bottom: 3px solid rgba(28, 46, 39, 0.6);
  border-radius: 0 0 10px 0;
}

.gas-station-board__display {
  border-radius: 12px;
  background: #101715;
  border: 1px solid #3f5149;
  padding: 10px 12px;
}

.gas-station-board__title {
  color: #d8efe4;
  font-weight: 800;
  font-size: 14px;
  letter-spacing: 0.4px;
}

.gas-station-board__sub {
  color: rgba(206, 231, 220, 0.72);
  font-size: 12px;
  margin-top: 2px;
  margin-bottom: 8px;
}

.gas-station-board__rows {
  display: grid;
  gap: 6px;
}

.gas-station-board__row {
  display: grid;
  grid-template-columns: 72px 44px minmax(0, 1fr);
  align-items: center;
  gap: 6px;
  border: 1px solid rgba(108, 153, 130, 0.28);
  border-radius: 8px;
  padding: 6px 8px;
  background: rgba(16, 44, 32, 0.58);
}

.gas-station-board__fuel-name {
  color: #c6ebd8;
  font-size: 12px;
  font-weight: 700;
  white-space: nowrap;
}

.gas-station-board__fuel-code {
  color: #83b39e;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.4px;
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
}

.gas-station-board__fuel-price {
  text-align: right;
  color: #53ff9e;
  font-family: "Consolas", "Courier New", monospace;
  font-size: 16px;
  line-height: 1;
  white-space: nowrap;
  word-break: keep-all;
}

.gas-station-board__fuel-price span {
  color: #abdbc5;
  margin-left: 4px;
  font-size: 11px;
  font-weight: 600;
  white-space: nowrap;
}

.gas-station-board--side .gas-station-board__row {
  grid-template-columns: 84px 42px minmax(0, 1fr);
}

.gas-station-board--side .gas-station-board__fuel-price {
  font-size: 14px;
}

@media (max-width: 860px) {
  .fuel-tab-layout {
    grid-template-columns: 1fr;
  }

  .fuel-tab-layout__left {
    justify-content: stretch;
  }

  .gas-station-board--side {
    width: 100%;
    margin: 0;
  }

  .gas-station-board {
    grid-template-columns: 1fr;
  }

  .gas-station-board--side .gas-station-board__pump {
    display: grid;
  }
}

.fuel-kiosk {
  --fuel-kiosk-stage-height: clamp(500px, 56vh, 620px);
  margin: 0;
  width: 100%;
  max-width: none;
  border: 1px solid rgba(45, 73, 58, 0.2);
  border-radius: 14px;
  background: #f6f7f2;
  padding: 10px;
  min-height: 460px;
  height: auto;
  display: flex;
  flex-direction: column;
  box-sizing: border-box;
}

.fuel-kiosk--compact {
  justify-content: flex-start;
  align-self: flex-start;
  min-height: 0;
  height: auto;
}

.fuel-tab-layout__right .fuel-kiosk--compact {
  align-self: center;
}

.fuel-kiosk__title {
  font-size: 16px;
  font-weight: 800;
  color: #204535;
  margin-bottom: 8px;
}

.fuel-kiosk__guide {
  font-size: 15px;
  font-weight: 700;
  color: rgba(31, 56, 45, 0.88);
  margin-bottom: 8px;
}

.fuel-kiosk__screen {
  border: 1px solid rgba(45, 73, 58, 0.2);
  border-radius: 12px;
  background: linear-gradient(180deg, #f8fbfa 0%, #eef4f1 100%);
  padding: 10px;
  min-height: 0;
  flex: 1;
  display: flex;
  flex-direction: column;
}

.fuel-kiosk__screen--compact {
  flex: 0 0 auto;
  max-height: none;
  min-height: var(--fuel-kiosk-stage-height);
  margin-top: 0;
  margin-bottom: 0;
}

.fuel-kiosk__screen--compact .fuel-kiosk__layout {
  flex: 0 0 auto;
}

.fuel-kiosk__screen--compact .fuel-kiosk__content {
  height: auto;
}

.fuel-kiosk__intro {
  border: 0;
  border-radius: 0;
  min-height: 0;
  flex: 1;
  background: transparent;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 14px;
}

.fuel-kiosk__intro-brand {
  font-size: 28px;
  font-weight: 800;
  color: #31584a;
}

.fuel-kiosk__intro-title {
  font-size: 44px;
  font-weight: 900;
  color: #234336;
  letter-spacing: 0.5px;
}

.fuel-kiosk__intro-start {
  min-width: 180px;
  min-height: 64px;
  border: 0;
  border-radius: 10px;
  background: linear-gradient(180deg, #2e7fd0 0%, #215da1 100%);
  color: #fff;
  font-size: 42px;
  font-weight: 900;
  letter-spacing: 6px;
  cursor: pointer;
}

.fuel-kiosk__intro-start.is-pressed,
.fuel-kiosk__intro-start:active {
  transform: translateY(2px) scale(0.995);
  filter: brightness(0.92);
  box-shadow: inset 0 2px 8px rgba(0, 0, 0, 0.26);
}

.fuel-kiosk__header {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  margin-bottom: 6px;
}

.fuel-kiosk__header strong {
  font-size: 20px;
  color: #1f4b38;
}

.fuel-kiosk__header span {
  font-size: 13px;
  color: rgba(31, 56, 45, 0.68);
}

.fuel-kiosk__back-btn {
  min-width: 52px;
  height: 30px;
  border: 1px solid #8d1f1f;
  border-radius: 4px;
  background: linear-gradient(180deg, #d74b4b 0%, #b62727 100%);
  color: #fff;
  font-size: 12px;
  font-weight: 800;
  cursor: pointer;
  padding: 0 10px;
  margin-top: 8px;
  -webkit-text-stroke: 0;
  text-shadow: none;
}

.fuel-kiosk__back-btn.is-pressed,
.fuel-kiosk__back-btn:active {
  transform: translateY(1px) scale(0.99);
  filter: brightness(0.93);
}

.fuel-kiosk__layout {
  display: grid;
  grid-template-columns: 130px minmax(0, 1fr);
  gap: 10px;
  min-height: 0;
  flex: 1;
}

.fuel-kiosk__side {
  display: grid;
  gap: 8px;
}

.fuel-kiosk__side-btn {
  min-height: 48px;
  border: 1px solid rgba(45, 73, 58, 0.2);
  border-radius: 10px;
  background: #e9efec;
  color: rgba(31, 56, 45, 0.55);
  font-weight: 700;
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
}

.fuel-kiosk__side-btn.is-active {
  border-color: rgba(52, 108, 86, 0.52);
  background: rgba(99, 145, 125, 0.2);
  color: rgba(25, 53, 41, 0.95);
}

.fuel-kiosk__side--steps .fuel-kiosk__side-btn {
  min-height: 58px;
}

.fuel-kiosk__content {
  min-width: 0;
  display: flex;
  flex-direction: column;
  min-height: 0;
  height: 100%;
  flex: 1;
  padding-left: 10px;
  box-sizing: border-box;
}

.fuel-kiosk__content--amount {
  display: block;
  min-height: 0;
}

.fuel-kiosk__content--payment {
  display: flex;
  min-height: 100%;
}

.fuel-kiosk__content--amount .fuel-kiosk-paypad--amount {
  flex: 0 0 auto;
}

.fuel-kiosk__content--payment .fuel-kiosk-paypad--payment {
  flex: 1;
}

.fuel-kiosk__type-buttons {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 10px;
  min-height: 0;
  flex: 0 0 auto;
}

.fuel-kiosk__type-buttons--kiosk {
  grid-template-columns: repeat(3, minmax(0, 1fr));
  height: auto;
  align-items: stretch;
}

.fuel-kiosk__type-buttons--offset {
  padding-top: 0;
}

.fuel-kiosk__type-buttons--single {
  grid-template-columns: minmax(180px, 320px);
  justify-content: center;
}

.fuel-kiosk__type-buttons .button {
  min-height: 44px;
  font-size: 18px;
  font-weight: 800;
}

.fuel-kiosk__tile {
  aspect-ratio: auto;
  min-height: 220px;
  height: clamp(220px, 34vh, 320px);
  border-radius: 12px;
  border: 2px solid rgba(255, 255, 255, 0.65);
  cursor: pointer;
  color: #f4fff8;
  font-size: 30px;
  font-weight: 900;
  letter-spacing: 0.6px;
  -webkit-text-stroke: 0;
  text-shadow: 0 1px 2px rgba(0, 0, 0, 0.26);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.28),
    inset 0 -14px 26px rgba(0, 0, 0, 0.16);
}

.fuel-kiosk__tile--diesel {
  background:
    radial-gradient(circle at 18% 12%, rgba(255, 255, 255, 0.22) 0%, rgba(255, 255, 255, 0) 38%),
    linear-gradient(180deg, #4b89da 0%, #2d64b8 48%, #1e4f9d 100%);
}

.fuel-kiosk__tile--gasoline {
  background:
    radial-gradient(circle at 20% 12%, rgba(255, 255, 255, 0.2) 0%, rgba(255, 255, 255, 0) 40%),
    linear-gradient(180deg, #e0bb3f 0%, #c79d1a 52%, #b78b09 100%);
}

.fuel-kiosk__tile--kerosene {
  background:
    radial-gradient(circle at 22% 12%, rgba(255, 255, 255, 0.2) 0%, rgba(255, 255, 255, 0) 40%),
    linear-gradient(180deg, #c2c9d0 0%, #a8b0b8 48%, #8f989f 100%);
}

.fuel-kiosk__tile--lpg {
  background:
    radial-gradient(circle at 18% 12%, rgba(255, 255, 255, 0.22) 0%, rgba(255, 255, 255, 0) 38%),
    linear-gradient(180deg, #8d63d8 0%, #6d43bc 48%, #562da4 100%);
}

.fuel-kiosk__tile.is-active {
  border-color: rgba(32, 84, 62, 0.58);
  box-shadow: 0 0 0 3px rgba(49, 108, 84, 0.25) inset;
}

.fuel-kiosk__tile.is-pressed,
.fuel-kiosk__tile:active {
  transform: translateY(2px) scale(0.995);
  filter: brightness(0.92);
  border-color: rgba(24, 61, 47, 0.72);
  box-shadow:
    inset 0 2px 8px rgba(0, 0, 0, 0.28),
    0 0 0 2px rgba(49, 108, 84, 0.35);
}

.fuel-kiosk__actions {
  margin-top: 10px;
  display: flex;
  gap: 8px;
  justify-content: center;
}

.fuel-kiosk__notice {
  margin-top: 10px;
  border-radius: 10px;
  background: #d22f2f;
  color: #fff;
  font-size: 14px;
  font-weight: 700;
  padding: 8px 10px;
}

.fuel-kiosk__row {
  display: grid;
  grid-template-columns: 90px minmax(0, 1fr);
  align-items: center;
  gap: 10px;
  margin-top: 8px;
}

.fuel-kiosk__row > span {
  font-size: 13px;
  color: rgba(31, 56, 45, 0.82);
  font-weight: 700;
}

.fuel-kiosk__qty {
  display: grid;
  grid-template-columns: repeat(3, auto) 108px;
  gap: 6px;
  align-items: center;
}

.fuel-kiosk__qty .button.is-active {
  border-color: rgba(32, 84, 62, 0.5);
  background: rgba(49, 108, 84, 0.12);
}

.fuel-kiosk__summary {
  margin-top: 10px;
  border-radius: 10px;
  border: 1px solid rgba(45, 73, 58, 0.14);
  background: rgba(255, 255, 255, 0.7);
  padding: 8px 10px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  color: rgba(31, 56, 45, 0.84);
}

.fuel-kiosk__summary strong {
  color: #1f4b38;
  font-size: 18px;
}

.fuel-kiosk-paypad {
  margin-top: 8px;
  padding: 8px;
  border: 1px solid rgba(45, 73, 58, 0.2);
  border-radius: 12px;
  background: linear-gradient(180deg, #eef2ef 0%, #e3e8e4 100%);
  display: grid;
  gap: 6px;
  box-sizing: border-box;
}

.fuel-kiosk-paypad--solo {
  flex: 1;
  margin-top: 0;
  align-content: start;
}

.fuel-kiosk-paypad--amount {
  margin-top: 0;
  height: 100%;
  grid-template-rows: auto auto auto;
  align-items: stretch;
}

.fuel-kiosk-paypad--amount .fuel-kiosk-paypad__quick {
  height: 100%;
  grid-template-rows: repeat(2, minmax(0, 1fr));
  align-items: stretch;
}

.fuel-kiosk-paypad--amount .fuel-kiosk-paypad__actions {
  height: 100%;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  align-items: stretch;
}

.fuel-kiosk-paypad--amount .fuel-kiosk-paypad__chip {
  min-height: 72px;
  height: auto;
  font-size: 24px;
  font-weight: 900;
  letter-spacing: 0.2px;
}

.fuel-kiosk-paypad--amount .fuel-kiosk-paypad__quick .fuel-kiosk-paypad__chip {
  font-size: 22px;
}

.fuel-kiosk-paypad--amount .fuel-kiosk-paypad__actions .fuel-kiosk-paypad__chip {
  font-size: 21px;
  min-height: 190px;
}

.fuel-kiosk-paypad--payment {
  height: 100%;
  align-content: stretch;
}

.fuel-kiosk-paypad--payment .fuel-kiosk-paypad__actions {
  height: 100%;
  align-items: stretch;
}

.fuel-kiosk-paypad--payment .fuel-kiosk-paypad__chip {
  min-height: 0;
  height: 100%;
  font-size: 34px;
  font-weight: 900;
}

.fuel-kiosk-paypad__quick {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 8px;
}

.fuel-kiosk-paypad__actions {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 8px;
}

.fuel-kiosk-paypad__actions--two {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.fuel-kiosk-custom__unit-row .fuel-kiosk-paypad__chip {
  min-height: 64px;
  font-size: 28px;
}

.fuel-kiosk-custom__display {
  margin-top: 8px;
  min-height: 72px;
  border-radius: 12px;
  border: 1px solid rgba(45, 73, 58, 0.2);
  background: rgba(255, 255, 255, 0.74);
  padding: 10px 14px;
  display: flex;
  align-items: baseline;
  justify-content: flex-end;
  gap: 8px;
}

.fuel-kiosk-custom__display strong {
  font-size: 36px;
  line-height: 1;
  color: #17392d;
}

.fuel-kiosk-custom__display span {
  font-size: 20px;
  font-weight: 800;
  color: rgba(23, 57, 45, 0.8);
}

.fuel-kiosk-custom__calc {
  margin-top: 8px;
  display: grid;
  grid-template-columns: minmax(0, 1fr) 86px;
  gap: 8px;
  align-items: stretch;
}

.fuel-kiosk-custom__pad {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 8px;
}

.fuel-kiosk-custom__digit {
  min-height: 56px;
  font-size: 24px;
  font-weight: 900;
}

.fuel-kiosk-custom__next {
  min-height: 100%;
  border-radius: 8px;
  border: 1px solid rgba(45, 73, 58, 0.35);
  background: linear-gradient(180deg, #f69730 0%, #df7615 100%);
  color: #fff;
  font-size: 26px;
  font-weight: 900;
  cursor: pointer;
}

.fuel-kiosk-paypad__chip {
  width: 100%;
  min-height: 44px;
  border-radius: 11px;
  border: 1px solid #9a530f;
  background: linear-gradient(180deg, #f69730 0%, #df7615 100%);
  color: #fff;
  font-size: 15px;
  font-weight: 800;
  cursor: pointer;
  box-sizing: border-box;
  padding: 0 8px;
  display: flex;
  align-items: center;
  justify-content: center;
  -webkit-text-stroke: 0;
  text-shadow: 0 1px 2px rgba(0, 0, 0, 0.22);
}

.fuel-kiosk-paypad__chip:hover {
  filter: brightness(1.03);
}

.fuel-kiosk-paypad__chip.is-pressed,
.fuel-kiosk-paypad__chip:active {
  transform: translateY(2px) scale(0.995);
  filter: brightness(0.93);
  box-shadow: inset 0 2px 8px rgba(0, 0, 0, 0.25);
}

.fuel-kiosk-paypad__chip.is-active {
  border-color: #356b55;
  box-shadow:
    0 0 0 2px rgba(53, 107, 85, 0.26) inset,
    0 1px 0 rgba(255, 255, 255, 0.32);
}

.fuel-kiosk-paypad__chip:focus-visible {
  outline: 0;
  box-shadow: 0 0 0 2px rgba(53, 107, 85, 0.38);
}

.fuel-kiosk-paypad__chip:disabled {
  opacity: 0.58;
  cursor: not-allowed;
  filter: grayscale(0.1);
}

.fuel-kiosk-paypad__chip--wide {
