.fuel-jerrycan__handle {
  position: absolute;
  left: 41px;
  top: 2px;
  width: 64px;
  height: 24px;
  border-radius: 13px 13px 10px 10px;
  z-index: 4;
  background: linear-gradient(180deg, var(--jerry-top-1) 0%, var(--jerry-top-2) 100%);
  border: 1px solid var(--jerry-top-edge);
  box-shadow:
    inset 0 1px 0 var(--jerry-top-gloss),
    0 2px 4px rgba(0, 0, 0, 0.14);
}

.fuel-jerrycan__handle::before {
  content: '';
  position: absolute;
  left: 11px;
  right: 11px;
  top: 5px;
  bottom: 6px;
  border-radius: 8px;
  background: linear-gradient(180deg, rgba(21, 39, 31, 0.2), rgba(21, 39, 31, 0.32));
