.fuel-jerrycan__handle::after {
  content: '';
  position: absolute;
  left: 16px;
  right: 16px;
  top: 9px;
  height: 1px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.28);
}

.fuel-jerrycan__cap {
  position: absolute;
  left: 26px;
  top: 8px;
  width: 13px;
  height: 13px;
  border-radius: 6px;
  z-index: 6;
  background: linear-gradient(180deg, var(--jerry-top-1) 0%, var(--jerry-top-2) 100%);
  border: 1px solid var(--jerry-top-edge);
  box-shadow:
    inset 0 1px 0 var(--jerry-top-gloss),
    0 1px 2px rgba(0, 0, 0, 0.25);
}

.fuel-jerrycan__cap::before {
  content: '';
  position: absolute;
  inset: 2px;
  border-radius: 4px;
  border: 1px solid rgba(20, 39, 30, 0.22);
}

.fuel-jerrycan__cap::after {
  content: '';
  position: absolute;
  left: 2px;
  right: 2px;
  top: 5px;
  height: 2px;
  border-radius: 999px;
  background: rgba(20, 39, 30, 0.25);
}

.fuel-jerrycan__body {
  position: absolute;
  left: 0;
  right: 0;
  top: 20px;
  bottom: 0;
  border-radius: 12px;
  border: 0;
  overflow: hidden;
  box-shadow:
    inset 10px 0 12px rgba(255, 255, 255, 0.14),
    inset -10px 0 14px rgba(0, 0, 0, 0.12),
    0 6px 16px rgba(5, 18, 12, 0.22);
  background: linear-gradient(150deg, #f2f5f4 0%, #dde4e1 52%, #c7d2cd 100%);
}

.fuel-jerrycan__body::before {
  content: '';
  position: absolute;
  left: 8%;
  top: 12%;
  width: 84%;
  height: 22%;
  border-radius: 999px;
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.18), rgba(255, 255, 255, 0));
  pointer-events: none;
  z-index: 2;
