.fuel-jerrycan__cross {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 66px;
  height: 4px;
  border-radius: 999px;
  background: rgba(20, 39, 30, 0.18);
  transform-origin: center;
  z-index: 3;
}

.fuel-jerrycan__cross--a {
  transform: translate(-50%, -50%) rotate(44deg);
}

.fuel-jerrycan__cross--b {
  transform: translate(-50%, -50%) rotate(-44deg);
}

.fuel-jerrycan--diesel .fuel-jerrycan__body {
