}

.fuel-jerrycan--diesel .fuel-jerrycan__spout,
.fuel-jerrycan--diesel .fuel-jerrycan__handle,
.fuel-jerrycan--diesel .fuel-jerrycan__cap {
  --jerry-top-1: #95a59f;
  --jerry-top-2: #788983;
}

.fuel-jerrycan--gasoline .fuel-jerrycan__body {
  background: linear-gradient(150deg, #f2f5f4 0%, #dde4e1 52%, #c7d2cd 100%);
}

.fuel-jerrycan--gasoline .fuel-jerrycan__spout,
.fuel-jerrycan--gasoline .fuel-jerrycan__handle,
.fuel-jerrycan--gasoline .fuel-jerrycan__cap {
  --jerry-top-1: #98a8a2;
  --jerry-top-2: #7a8b85;
}

.fuel-jerrycan--kerosene .fuel-jerrycan__body {
  background: linear-gradient(150deg, #f2f5f4 0%, #dde4e1 52%, #c7d2cd 100%);
}

.fuel-jerrycan--kerosene .fuel-jerrycan__spout,
.fuel-jerrycan--kerosene .fuel-jerrycan__handle,
.fuel-jerrycan--kerosene .fuel-jerrycan__cap {
  --jerry-top-1: #93a49e;
  --jerry-top-2: #758781;
}

.fuel-kiosk-fill-anim__liquid {
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  height: calc(var(--fuel-fill-ratio, 0) * 100%);
  z-index: 1;
  transition: none;
  opacity: 1;
  background: var(--fuel-liquid-solid, #54d9a7) !important;
  overflow: hidden;
}

.fuel-kiosk-fill-anim__liquid::before {
  content: '';
  position: absolute;
  left: -120%;
  top: -10px;
  width: 240%;
  height: 22px;
  border-radius: 40% 60% 48% 52% / 55% 45% 55% 45%;
  background: rgba(255, 255, 255, 0.22);
  transform-origin: 50% 100%;
  animation: fuelLiquidWave 2.6s linear infinite, fuelLiquidCrest 2.1s ease-in-out infinite;
}

.fuel-kiosk-fill-anim.is-running .fuel-kiosk-fill-anim__tube::after {
  animation: fuelTubeFlow 0.9s linear forwards;
}

.fuel-kiosk-fill-anim.is-running .fuel-kiosk-fill-anim__liquid {
  transition: height 4s ease-in-out;
  transition-delay: 0.9s;
  height: calc(var(--fuel-fill-ratio, 0.24) * 100%);
  animation: none;
}

.fuel-kiosk-fill-anim.is-done .fuel-kiosk-fill-anim__liquid {
  transition: none;
  height: calc(var(--fuel-fill-ratio, 0.24) * 100%);
  animation: none;
}


@keyframes fuelTubeFlow {
  0% {
    width: 0;
  }
  100% {
    width: 100%;
  }
}

@keyframes fuelLiquidWave {
  0% {
    left: -120%;
  }
  100% {
    left: -85%;
  }
}

@keyframes fuelLiquidSway {
  0% {
    transform: translateY(0);
  }
  20% {
    transform: translateY(-0.5px);
  }
  40% {
    transform: translateY(-1.1px);
  }
  60% {
    transform: translateY(-1.5px);
  }
  80% {
    transform: translateY(-0.8px);
  }
  100% {
    transform: translateY(0);
  }
}

@keyframes fuelLiquidCrest {
  0% {
    transform: translateY(0) scaleX(1);
  }
  30% {
    transform: translateY(-0.7px) scaleX(1.01);
  }
  55% {
    transform: translateY(-1.2px) scaleX(1.018);
  }
  80% {
    transform: translateY(-0.6px) scaleX(1.01);
  }
  100% {
    transform: translateY(0) scaleX(1);
  }
}

@keyframes fuelKioskVehicleTankPulse {
  0% {
    transform: translateY(0) scale(1);
    filter: brightness(1);
  }
  50% {
    transform: translateY(-1px) scale(1.015);
    filter: brightness(1.06);
  }
  100% {
    transform: translateY(0) scale(1);
    filter: brightness(1);
  }
}

@keyframes fuelKioskVehicleTankShine {
  0% {
    opacity: 0.42;
  }
  50% {
    opacity: 0.9;
  }
  100% {
    opacity: 0.42;
  }
}

